/// A second notation, for the canvas test alone: diagrams of a UML package showing its classes as
/// cards (their attributes, then their operations) and their generalizations as lines with a
/// triangle and a text at the specific end.
struct Sketch;

const SKETCH: &str = "test.sketch";

impl archforge_diagram::Notation for Sketch {
    fn name(&self) -> &'static str {
        "Sketch"
    }
    fn metamodel(&self) -> u16 {
        archforge_uml::INDEX
    }
    fn kinds(&self) -> &'static [&'static str] {
        &[SKETCH]
    }
    fn is_of(&self, _: &str, class: archforge_mof::ClassId) -> bool {
        class == archforge_uml::PACKAGE
    }
    fn shows(&self, _: &str, class: archforge_mof::ClassId) -> bool {
        class == archforge_uml::CLASS
    }
    fn connects(&self, _: &str, class: archforge_mof::ClassId) -> bool {
        class == archforge_uml::GENERALIZATION
    }
    fn ends(&self, store: &archforge_mof::Store, element: archforge_mof::Obj) -> Option<(archforge_mof::Obj, archforge_mof::Obj)> {
        let specific = store.container(element).ok()??.0;
        let general = store.get(element, archforge_uml::generalization::GENERAL).ok()?.as_ref()?;
        Some((specific, general))
    }
    fn card(&self, store: &archforge_mof::Store, element: archforge_mof::Obj, _: archforge_mof::Obj) -> Option<archforge_diagram::figure::Card> {
        use archforge_diagram::figure::{Card, Row, Text};
        let rows = |prop| {
            store
                .list(element, prop)
                .unwrap_or_default()
                .iter()
                .filter_map(archforge_mof::Value::as_ref)
                .map(|o| Row { mark: None, text: archforge_core::name_of(store, o), linked: false, slanted: false, underlined: false })
                .collect::<Vec<_>>()
        };
        Some(Card {
            eyebrow: Text::Plain("Class".into()),
            name: archforge_core::name_of(store, element),
            compartments: vec![rows(archforge_uml::class::OWNED_ATTRIBUTE), rows(archforge_uml::class::OWNED_OPERATION)],
            more: ("+ {n} more column", "+ {n} more columns"),
            hidden: 0,
            elsewhere: false,
            tone: archforge_diagram::figure::Tone::Tinted,
            slanted: false,
            braces: None,
            template: Vec::new(),
        })
    }
    fn line(&self, _: &archforge_mof::Store, _: archforge_mof::Obj) -> Option<archforge_diagram::figure::Line> {
        use archforge_diagram::figure::{End, EndMark, Line};
        Some(Line {
            ends: [
                End { mark: EndMark::None, text: Some("specific".into()), slot: "sketch.specific", role: None, qualifiers: Vec::new() },
                End::marked(EndMark::Triangle),
            ],
            styled: true,
            dashed: false,
            status: None,
            note: None,
            badge: false,
            resolvable: false,
            keyword: None,
        })
    }
}

static SKETCHED: &[&dyn archforge_diagram::Notation] = &[&archforge_er::ErNotation, &Sketch];

/// Every text the last frame painted.
/// The colours the text `label` is laid out in, where it is painted inside `within`.
fn label_colours(h: &Harness<'static, Shell>, label: &str, within: egui::Rect) -> Vec<egui::Color32> {
    fn walk(s: &egui::Shape, label: &str, within: egui::Rect, out: &mut Vec<egui::Color32>) {
        match s {
            egui::Shape::Text(t) if t.galley.text() == label && within.contains(t.pos) => {
                out.extend(t.galley.job.sections.iter().map(|section| section.format.color));
            }
            egui::Shape::Vec(v) => v.iter().for_each(|s| walk(s, label, within, out)),
            _ => {}
        }
    }
    let mut out = Vec::new();
    h.output().shapes.iter().for_each(|c| walk(&c.shape, label, within, &mut out));
    out
}

/// The texts painted with their top left inside `r`, each with how many glyphs it was laid out in.
fn texts_in(h: &Harness<'static, Shell>, r: egui::Rect) -> Vec<(String, usize)> {
    fn walk(s: &egui::Shape, r: egui::Rect, out: &mut Vec<(String, usize)>) {
        match s {
            egui::Shape::Text(t) if r.contains(t.pos) => {
                out.push((t.galley.text().to_string(), t.galley.rows.iter().map(|row| row.glyphs.len()).sum()))
            }
            egui::Shape::Vec(v) => v.iter().for_each(|s| walk(s, r, out)),
            _ => {}
        }
    }
    let mut out = Vec::new();
    h.output().shapes.iter().for_each(|c| walk(&c.shape, r, &mut out));
    out
}

fn painted(h: &Harness<'static, Shell>) -> Vec<String> {
    fn walk(s: &egui::Shape, out: &mut Vec<String>) {
        match s {
            egui::Shape::Text(t) => out.push(t.galley.text().to_string()),
            egui::Shape::Vec(v) => v.iter().for_each(|s| walk(s, out)),
            _ => {}
        }
    }
    let mut out = Vec::new();
    h.output().shapes.iter().for_each(|c| walk(&c.shape, &mut out));
    out
}

/// A workspace whose session holds the sketch notation beside ER, with a sketch diagram of a
/// package: Party at the left, Customer at the right, Customer a kind of Party. Gives the diagram,
/// Party's node, Customer's node and the line's edge.
fn sketch_harness() -> (Harness<'static, Shell>, String, String, String, String) {
    use archforge_mof::Value;
    let mut h = workspace_harness(ThemeKind::Light, egui::vec2(1600.0, 1000.0));
    // A package with Party and Customer, Customer a kind of Party, in a session that holds the
    // sketch notation beside ER.
    let mut st = archforge_notations::store(Box::new({
        let ids = test_ids();
        move || ids()
    }))
    .unwrap();
    let model = st.create(archforge_core::MODEL).unwrap();
    let pkg = st.create(archforge_uml::PACKAGE).unwrap();
    archforge_uml::PackageObj::set_name(&mut st, pkg, Some("sales")).unwrap();
    archforge_core::ModelObj::push_member(&mut st, model, Value::Ref(pkg)).unwrap();
    let class = |st: &mut archforge_mof::Store, name: &str, parts: &[(&str, archforge_mof::ClassId, archforge_mof::PropId)]| {
        let c = st.create(archforge_uml::CLASS).unwrap();
        archforge_uml::ClassObj::set_name(st, c, Some(name)).unwrap();
        st.push(pkg, archforge_uml::package::PACKAGED_ELEMENT, Value::Ref(c)).unwrap();
        for (part, kind, prop) in parts {
            let o = st.create(*kind).unwrap();
            st.set(o, archforge_uml::named_element::NAME, Value::str(part)).unwrap();
            st.push(c, *prop, Value::Ref(o)).unwrap();
        }
        c
    };
    let party = class(
        &mut st,
        "Party",
        &[
            ("partyId", archforge_uml::PROPERTY, archforge_uml::class::OWNED_ATTRIBUTE),
            ("rename", archforge_uml::OPERATION, archforge_uml::class::OWNED_OPERATION),
        ],
    );
    let customer = class(&mut st, "Customer", &[("since", archforge_uml::PROPERTY, archforge_uml::class::OWNED_ATTRIBUTE)]);
    let g = st.create(archforge_uml::GENERALIZATION).unwrap();
    st.set(g, archforge_uml::generalization::GENERAL, Value::Ref(party)).unwrap();
    st.push(customer, archforge_uml::classifier::GENERALIZATION, Value::Ref(g)).unwrap();
    let uuid = |st: &archforge_mof::Store, o| st.uuid(o).unwrap().to_string();
    let (pkg_id, party_id, customer_id, g_id) = (uuid(&st, pkg), uuid(&st, party), uuid(&st, customer), uuid(&st, g));
    let mut s = archforge_engine::Session::with_view(
        archforge_notations::registry().unwrap(),
        st,
        1,
        archforge_engine::Options::default(),
        archforge_diagram::ProjectView::new(SKETCHED),
    );
    let id = |v: serde_json::Value| v["id"].as_str().unwrap().to_string();
    let d = id(s.execute("diagram.add", &serde_json::json!({ "kind": SKETCH, "element": pkg_id })).unwrap().value);
    let a = id(s
        .execute("diagram.place", &serde_json::json!({ "diagram": d, "element": party_id, "x": 100, "y": 100, "width": 240, "height": 166 }))
        .unwrap()
        .value);
    let b = id(s
        .execute("diagram.place", &serde_json::json!({ "diagram": d, "element": customer_id, "x": 600, "y": 100, "width": 240, "height": 166 }))
        .unwrap()
        .value);
    let e = id(s.execute("diagram.connect", &serde_json::json!({ "diagram": d, "element": g_id, "source": b, "target": a })).unwrap().value);
    h.state_mut().session = Some(s);
    h.state_mut().kinds = SKETCH_KINDS;
    h.state_mut().notation_uis = SKETCH_UIS;
    crate::canvas::open(h.state_mut(), archforge_mof::Uuid::parse(&d).unwrap());
    h.run();
    (h, d, a, b, e)
}

#[test]
fn a_second_notations_cards_and_lines_draw_route_arrange_and_take_their_look_on_the_same_canvas() {
    let (mut h, d, a, b, e) = sketch_harness();
    // The cards and the line, drawn through the one canvas from the sketch's descriptions.
    let texts = painted(&h);
    for t in ["CLASS", "Party", "partyId", "rename", "Customer", "since", "specific"] {
        assert!(texts.iter().any(|x| x == t), "{t} is drawn: {texts:?}");
    }
    let found = ids(&h);
    assert_eq!(found.iter().filter(|i| i.starts_with("workspace.canvas.node.")).count(), 2);
    assert!(found.iter().any(|i| *i == format!("workspace.canvas.edge.{e}")));
    assert_eq!(h.state().canvas.ends.len(), 1, "the specific end's text, which the user may move");
    // Routed: at right angles around nothing, as a new diagram's lines run.
    let (dobj, eobj, aobj, bobj) = {
        let st = h.state().session.as_ref().unwrap().doc();
        let o = |x: &str| st.by_uuid(archforge_mof::Uuid::parse(x).unwrap()).unwrap();
        (o(&d), o(&e), o(&a), o(&b))
    };
    let route = archforge_diagram::Grid::build(h.state().session.as_ref().unwrap().doc(), dobj).line(eobj).unwrap().to_vec();
    assert!(route.len() >= 2, "{route:?}");
    // Arranged: Customer, where the line starts, above Party.
    let at = rect_of(&h, "workspace.tools.arrange").center();
    click(&mut h, at);
    h.run();
    let st = h.state().session.as_ref().unwrap().doc();
    let (top, bottom) = (archforge_diagram::grid::bounds_of(st, bobj), archforge_diagram::grid::bounds_of(st, aobj));
    assert!(top.y + top.height <= bottom.y, "Customer above Party: {top:?} {bottom:?}");
    // Its look: a fill of its own on Party's card.
    h.state_mut().session.as_mut().unwrap().execute("diagram.style", &serde_json::json!({ "ids": [a], "fill": "#A0C4FF" })).unwrap();
    h.run();
    assert_eq!(look(&h, aobj).fill, crate::canvas::colour("#A0C4FF"));
    let filled = h.output().shapes.iter().any(|c| matches!(&c.shape, egui::Shape::Rect(r) if Some(r.fill) == crate::canvas::colour("#A0C4FF")));
    assert!(filled, "the card is filled in its own colour");
}

/// What the sketch kind's hooks were asked, in order.
static SKETCH_CALLS: std::sync::Mutex<Vec<String>> = std::sync::Mutex::new(Vec::new());

/// The sketch diagram kind in the shell, for the tests alone: a Class tool that places and an
/// Inherit tool that connects, each hook writing down what it was asked.
struct SketchKind;

static SKETCH_TOOLS: &[crate::kinds::KindTool] = &[
    crate::kinds::KindTool {
        key: "class",
        icon: &crate::ux::icons::TOOL_ENTITY,
        hint: "Entity",
        use_: crate::kinds::ToolUse::Place,
        chevron: None,
        wide: false,
    },
    crate::kinds::KindTool {
        key: "inherit",
        icon: &crate::ux::icons::TOOL_RELATIONSHIP,
        hint: "Relationship",
        use_: crate::kinds::ToolUse::Connect,
        chevron: None,
        wide: false,
    },
];

impl crate::kinds::DiagramKind for SketchKind {
    fn kind(&self) -> &'static str {
        SKETCH
    }
    fn tools(&self) -> &'static [crate::kinds::KindTool] {
        SKETCH_TOOLS
    }
    fn word(&self) -> String {
        "Sketch".into()
    }
    fn group_word(&self) -> String {
        "Sketches".into()
    }
    fn description(&self) -> String {
        "A sketch of classes".into()
    }
    fn new_word(&self) -> String {
        "New sketch".into()
    }
    fn owner_word(&self) -> String {
        "Package".into()
    }
    fn new_owner(&self) -> String {
        "New package".into()
    }
    fn owners(&self, store: &archforge_mof::Store) -> Vec<archforge_mof::Obj> {
        archforge_uml::commands::packages(store)
    }
    fn owner_of(&self, _: &archforge_mof::Store, _: archforge_mof::Obj) -> Option<archforge_mof::Obj> {
        None
    }
    fn add_owner(&self, _: &mut Shell, _: &str) -> Result<String, String> {
        Err("the sketch makes no package".into())
    }
    fn takes_part(&self, store: &archforge_mof::Store, element: archforge_mof::Obj) -> bool {
        store.class_of(element).ok() == Some(archforge_uml::CLASS)
    }
    fn place(&self, _: &mut Shell, tool: &'static str, _: archforge_mof::Obj, _: f64, _: f64) {
        SKETCH_CALLS.lock().unwrap().push(format!("place {tool}"));
    }
    fn connect(&self, shell: &mut Shell, tool: &'static str, _: archforge_mof::Obj, from: archforge_mof::Uuid, to: archforge_mof::Uuid) {
        let name = |id| {
            shell.session.as_ref().and_then(|s| {
                let st = s.doc();
                let e = st.get(st.by_uuid(id)?, archforge_diagram::node::ELEMENT).ok()?.as_ref()?;
                Some(archforge_core::name_of(st, e))
            })
        };
        SKETCH_CALLS.lock().unwrap().push(format!("connect {tool} {} {}", name(from).unwrap_or_default(), name(to).unwrap_or_default()));
    }
    fn connect_to_new(&self, _: &mut Shell, tool: &'static str, _: archforge_mof::Obj, _: archforge_mof::Uuid, _: f64, _: f64) {
        SKETCH_CALLS.lock().unwrap().push(format!("connect to new {tool}"));
    }
    fn rename(&self, _: &mut Shell, _: archforge_mof::Uuid, name: &str) -> Result<(), String> {
        SKETCH_CALLS.lock().unwrap().push(format!("rename {name}"));
        Ok(())
    }
    fn open(&self, _: &mut Shell, _: archforge_mof::Uuid, row: Option<usize>) {
        SKETCH_CALLS.lock().unwrap().push(format!("open {row:?}"));
    }
}

static SKETCH_KINDS: &[&dyn crate::kinds::DiagramKind] = &[&crate::er_kind::ErKind, &SketchKind];

#[test]
fn a_second_kinds_toolbar_shows_its_own_tools_and_its_place_connect_and_rename_hooks_run() {
    let (mut h, _d, a, b, _e) = sketch_harness();
    SKETCH_CALLS.lock().unwrap().clear();
    // ER's tool, left on from an ER diagram, is not the sketch's: the toolbar hands back to Select.
    h.state_mut().canvas.tool = crate::canvas::Tool::Place("entity");
    h.run();
    assert_eq!(h.state().canvas.tool, crate::canvas::Tool::Select);
    let found = ids(&h);
    for shared in ["select", "pan", "class", "inherit", "note", "link", "grid", "arrange"] {
        assert!(found.iter().any(|i| *i == format!("workspace.tools.{shared}")), "{shared} is on the toolbar: {found:?}");
    }
    for er in ["entity", "relationship", "relationship-types", "key-status"] {
        assert!(!found.iter().any(|i| *i == format!("workspace.tools.{er}")), "ER's {er} is not");
    }
    // The toolbar keeps its order: Select, Pan, the kind's tools, Note, Link note, Grid, Arrange.
    let left = |key: &str| rect_of(&h, &format!("workspace.tools.{key}")).left();
    let xs: Vec<f32> = ["select", "pan", "class", "inherit", "note", "link", "grid", "arrange"].iter().map(|k| left(k)).collect();
    assert!(xs.windows(2).all(|w| w[0] < w[1]), "{xs:?}");
    // Class places where the canvas is clicked.
    let at = rect_of(&h, "workspace.tools.class").center();
    click(&mut h, at);
    assert_eq!(h.state().canvas.tool, crate::canvas::Tool::Place("class"));
    let canvas = rect_of(&h, "workspace.canvas");
    click(&mut h, canvas.left_top() + egui::vec2(40.0, 40.0));
    // Inherit connects Customer to Party, and dropped on empty canvas asks for a new class.
    let at = rect_of(&h, "workspace.tools.inherit").center();
    click(&mut h, at);
    assert_eq!(h.state().canvas.tool, crate::canvas::Tool::Connect("inherit"));
    let (party, customer) = (rect_of(&h, &format!("workspace.canvas.node.{a}")), rect_of(&h, &format!("workspace.canvas.node.{b}")));
    drag(&mut h, customer.center(), party.center());
    let at = rect_of(&h, "workspace.tools.inherit").center();
    click(&mut h, at);
    drag(&mut h, customer.center(), egui::pos2(customer.center().x, canvas.bottom() - 120.0));
    // A double click on Party's header names it in place, and Enter hands the name to the kind.
    for _ in 0..45 {
        h.step();
    }
    double_click(&mut h, party.left_top() + egui::vec2(60.0, 30.0));
    assert!(h.state().canvas.rename.as_ref().is_some_and(|r| r.text == "Party"), "{:?}", h.state().canvas.rename);
    h.state_mut().canvas.rename.as_mut().unwrap().text = "Person".into();
    key(&mut h, egui::Key::Enter, egui::Modifiers::NONE);
    assert!(h.state().canvas.rename.is_none());
    // A double click on a row opens the kind's editor there.
    for _ in 0..45 {
        h.step();
    }
    double_click(&mut h, party.left_top() + egui::vec2(100.0, 77.0 + 6.0));
    assert_eq!(
        *SKETCH_CALLS.lock().unwrap(),
        ["place class", "connect inherit Customer Party", "connect to new inherit", "rename Person", "open Some(0)"]
    );
}

/// The sketch notation in the shell's explorers, search and panels, for the tests alone: a package
/// at the top of the Models tree with its classes under it, each class found by the search as a
/// Class of its package, and a class's Properties a section of its attributes.
struct SketchUi;

fn sketch_classes(store: &archforge_mof::Store, pkg: archforge_mof::Obj) -> Vec<archforge_mof::Obj> {
    store
        .list(pkg, archforge_uml::package::PACKAGED_ELEMENT)
        .unwrap_or_default()
        .iter()
        .filter_map(archforge_mof::Value::as_ref)
        .filter(|o| store.class_of(*o).ok() == Some(archforge_uml::CLASS))
        .collect()
}

impl crate::notation_ui::NotationUi for SketchUi {
    fn metamodel(&self) -> u16 {
        archforge_uml::INDEX
    }
    fn is_top(&self, store: &archforge_mof::Store, member: archforge_mof::Obj) -> bool {
        store.class_of(member).ok() == Some(archforge_uml::PACKAGE)
    }
    fn tree(&self, store: &archforge_mof::Store, pkg: archforge_mof::Obj, t: &crate::explorer::Tree<'_>) -> Vec<crate::explorer::Row> {
        let classes = sketch_classes(store, pkg);
        let under: Vec<crate::explorer::Row> = classes
            .iter()
            .filter_map(|c| {
                let label = archforge_core::name_of(store, *c);
                if t.matches(&label) { t.row(*c, 1, "class", &crate::ux::icons::TABLE, label) } else { None }
            })
            .collect();
        let expandable = !under.is_empty();
        let expanded = expandable && t.open(pkg);
        let mut out: Vec<crate::explorer::Row> = t
            .row(pkg, 0, "package", &crate::ux::icons::SCHEMA, archforge_core::name_of(store, pkg))
            .map(|r| crate::explorer::Row { expandable, expanded, ..r })
            .into_iter()
            .collect();
        if expanded {
            out.extend(under);
        }
        out
    }
    fn offers(&self, _: &archforge_mof::Store, _: Option<archforge_mof::Obj>) -> Vec<crate::notation_ui::Offer> {
        Vec::new()
    }
    fn add(&self, _: &mut Shell, _: &str, _: Option<archforge_mof::Obj>) -> Option<Result<crate::notation_ui::Added, String>> {
        None
    }
    fn rename(&self, _: &archforge_mof::Store, _: archforge_mof::Obj) -> Option<(&'static str, &'static str)> {
        None
    }
    fn foldable(&self, _: &archforge_mof::Store, pkg: archforge_mof::Obj) -> Vec<archforge_mof::Obj> {
        vec![pkg]
    }
    fn parents(&self, store: &archforge_mof::Store, o: archforge_mof::Obj) -> Vec<archforge_mof::Obj> {
        store.container(o).ok().flatten().map(|(c, _)| c).into_iter().collect()
    }
    fn entry(&self, store: &archforge_mof::Store, o: archforge_mof::Obj) -> Option<crate::notation_ui::Entry> {
        (store.class_of(o).ok()? == archforge_uml::CLASS).then(|| {
            let pkg = store.container(o).ok().flatten().map(|(c, _)| archforge_core::name_of(store, c)).unwrap_or_default();
            crate::notation_ui::Entry {
                icon: &crate::ux::icons::TABLE,
                order: 2,
                label: archforge_core::name_of(store, o),
                detail: format!("Class · {pkg}"),
            }
        })
    }
    fn words(&self, store: &archforge_mof::Store, o: archforge_mof::Obj) -> Option<crate::notation_ui::Words> {
        Some(crate::notation_ui::Words {
            kind: "Class · sketch".into(),
            word: "Class".into(),
            this: "This class".into(),
            on_this: "On this class · {n}".into(),
            name: archforge_core::name_of(store, o),
        })
    }
    fn body(&self, shell: &mut Shell, ui: &mut egui::Ui, p: &crate::ux::Palette, r: egui::Rect, y: f32, subject: &crate::panels::Subject) {
        let attributes = shell
            .session
            .as_ref()
            .and_then(|s| {
                let store = s.doc();
                Some(
                    store
                        .list(subject.obj?, archforge_uml::class::OWNED_ATTRIBUTE)
                        .ok()?
                        .iter()
                        .filter_map(archforge_mof::Value::as_ref)
                        .map(|a| archforge_core::name_of(store, a))
                        .collect::<Vec<_>>(),
                )
            })
            .unwrap_or_default();
        let y = crate::panels::section(shell, ui, p, r, y, "Attributes", None).unwrap_or(y + 50.0);
        for (i, a) in attributes.iter().enumerate() {
            let row = egui::Rect::from_min_size(egui::pos2(r.left() + 16.0, y + i as f32 * 28.0), egui::vec2(r.width() - 32.0, 24.0));
            crate::home::control(shell, ui, &format!("workspace.properties.sketch.attribute.{i}"), "row", row, true);
            crate::ux::text(&ui.painter().clone(), row.min, a, crate::ux::types::UI, p.text, None);
        }
    }
}

static SKETCH_UIS: &[&dyn crate::notation_ui::NotationUi] = &[&crate::er_ui::ErUi, &SketchUi];

#[test]
fn a_second_notations_elements_show_in_the_tree_are_found_and_get_their_own_properties() {
    let (mut h, ..) = sketch_harness();
    let st = h.state().session.as_ref().unwrap().doc();
    let o = |name: &str| st.alive().find(|o| archforge_core::name_of(st, *o) == name).unwrap();
    let (pkg, party) = (o("sales"), o("Party"));
    let (pkg_id, party_id) = (st.uuid(pkg).unwrap(), st.uuid(party).unwrap());
    // The tree: the package at the top, its classes under it once it is open.
    let rows = |h: &Harness<'static, Shell>| {
        crate::explorer::rows(h.state().notation_uis, h.state().session.as_ref().unwrap().doc(), &h.state().explorer)
            .into_iter()
            .map(|r| (r.depth, r.label))
            .collect::<Vec<_>>()
    };
    assert_eq!(rows(&h), [(0, "sales".to_string())]);
    h.state_mut().explorer.expanded.insert(pkg_id);
    h.run();
    assert_eq!(rows(&h), [(0, "sales".to_string()), (1, "Party".to_string()), (1, "Customer".to_string())]);
    assert!(ids(&h).iter().any(|i| *i == format!("workspace.explorer.row.{party_id}")), "the class has a row");
    // The search finds a class as its notation lists it.
    let index = crate::project_search::index(h.state().kinds, h.state().notation_uis, h.state().session.as_ref().unwrap().doc());
    let (_, found) = crate::project_search::hits(&index, "part");
    assert!(found.iter().any(|e| e.label == "Party" && e.detail == "Class · sales"), "{:?}", found.iter().map(|e| &e.label).collect::<Vec<_>>());
    // Properties: the class's own words and its notation's section.
    h.state_mut().session.as_mut().unwrap().execute("view.select", &serde_json::json!({ "ids": [party_id.to_string()] })).unwrap();
    h.state_mut().state.show_panel(crate::state::Panel::Properties);
    h.run();
    let texts = painted(&h);
    assert!(texts.iter().any(|t| t == "Class · sketch"), "{texts:?}");
    assert!(ids(&h).iter().any(|i| i == "workspace.properties.sketch.attribute.0"), "the class's attributes section");
}

/// The class diagram the canvas shows, and its classes' names on it.
fn class_diagram_shown(h: &Harness<'static, Shell>) -> (String, Vec<String>) {
    let st = h.state().session.as_ref().unwrap().doc();
    let d = st.by_uuid(h.state().canvas.active.expect("a diagram is open")).unwrap();
    let kind = st.get(d, archforge_diagram::diagram::KIND).unwrap().as_str().unwrap().to_string();
    let classes = st
        .list(d, archforge_diagram::diagram::NODE)
        .unwrap()
        .iter()
        .filter_map(archforge_mof::Value::as_ref)
        .filter_map(|n| st.get(n, archforge_diagram::node::ELEMENT).ok()?.as_ref())
        .map(|e| archforge_core::name_of(st, e))
        .collect();
    (kind, classes)
}

/// A class diagram is made in three steps, and its classifier tool places a class named in place.
#[test]
fn a_new_project_makes_a_class_diagram_in_three_steps_and_its_class_tool_places_a_class_named_in_place() {
    let mut h = workspace_harness(ThemeKind::Light, egui::vec2(1600.0, 1000.0));
    // 1. The tab strip's + opens New diagram; 2. the Class diagram card, Continue; 3. Create.
    let at = rect_of(&h, "workspace.tabs.add").center();
    click(&mut h, at);
    let at = rect_of(&h, "workspace.new-diagram.type.uml.class").center();
    click(&mut h, at);
    let at = rect_of(&h, "workspace.new-diagram.continue").center();
    click(&mut h, at);
    let edit = h.state().diagrams.new.clone().expect("the dialog is open");
    assert_eq!(edit.kind, archforge_uml::CLASS_DIAGRAM);
    assert_eq!(edit.schema, None, "a project without a package gets its root package");
    assert!(painted(&h).iter().any(|t| t == "Commerce platform"), "the Package field names the root, after the project");
    h.state_mut().diagrams.new.as_mut().unwrap().name = "Domain".into();
    let at = rect_of(&h, "workspace.new-diagram.create").center();
    click(&mut h, at);
    assert!(h.state().diagrams.new.is_none(), "{:?}", h.state().diagrams.new);
    assert_eq!(class_diagram_shown(&h), (archforge_uml::CLASS_DIAGRAM.to_string(), Vec::new()), "an empty class diagram is open");
    // The diagram is of the model's root package, named after the project; no other package.
    let st = h.state().session.as_ref().unwrap().doc();
    let root = archforge_uml::commands::root_package(st).expect("the root package is made");
    assert_eq!(archforge_uml::commands::all_packages(st), vec![root]);
    assert_eq!(archforge_core::name_of(st, root), "Commerce platform");
    let shown = st.by_uuid(h.state().canvas.active.expect("a diagram is open")).unwrap();
    assert_eq!(st.get(shown, archforge_diagram::diagram::ELEMENT).unwrap().as_ref(), Some(root));
    // Its toolbar: Class, Relationship with its kinds, Note and Link note; ER's tools and its key
    // status are not there.
    let found = ids(&h);
    for tool in ["select", "pan", "classifier", "classifier-kinds", "relationship", "relationship-kinds", "note", "link", "grid", "arrange"] {
        assert!(found.iter().any(|i| *i == format!("workspace.tools.{tool}")), "{tool}");
    }
    for er in ["entity", "relationship-types", "key-status"] {
        assert!(!found.iter().any(|i| *i == format!("workspace.tools.{er}")), "{er}");
    }
    // A click in Select adds nothing; with the Class tool it places a class, named in place.
    let canvas = rect_of(&h, "workspace.canvas");
    click(&mut h, canvas.center());
    assert!(class_diagram_shown(&h).1.is_empty(), "Select adds nothing");
    let at = rect_of(&h, "workspace.tools.classifier").center();
    click(&mut h, at);
    click(&mut h, canvas.center());
    assert_eq!(class_diagram_shown(&h).1, ["Class 1"]);
    assert_eq!(h.state().canvas.tool, crate::canvas::Tool::Select, "the tool hands back to Select");
    let rename = h.state().canvas.rename.clone().expect("the class's name is open for typing");
    assert_eq!(rename.text, "Class 1");
    h.state_mut().canvas.rename.as_mut().unwrap().text = "Order".into();
    key(&mut h, egui::Key::Enter, egui::Modifiers::NONE);
    assert_eq!(class_diagram_shown(&h).1, ["Order"]);
    // The tree shows the root package, after the project, with its class; the search finds it.
    let st = h.state().session.as_ref().unwrap().doc();
    let pkg = st.uuid(archforge_uml::commands::packages(st)[0]).unwrap();
    h.state_mut().explorer.expanded.insert(pkg);
    let rows: Vec<String> = crate::explorer::rows(h.state().notation_uis, h.state().session.as_ref().unwrap().doc(), &h.state().explorer)
        .into_iter()
        .map(|r| r.label)
        .collect();
    assert_eq!(rows, ["Commerce platform", "Order"]);
    let index = crate::project_search::index(h.state().kinds, h.state().notation_uis, h.state().session.as_ref().unwrap().doc());
    assert!(crate::project_search::hits(&index, "ord").1.iter().any(|e| e.label == "Order"));
    // Saved and opened again, as the project's rows: the class diagram comes back.
    let (tables, junctions) = archforge_notations::storage();
    let rows = archforge_mof::rows::snapshot(h.state().session.as_ref().unwrap().doc(), &tables, &junctions).unwrap();
    let back = archforge_notations::session_from_rows(&rows, Box::new(|| archforge_mof::Uuid::v7(1_761_670_900_000, [9; 10]))).unwrap();
    let st = back.doc();
    let d = st.alive().find(|o| st.class_of(*o).ok() == Some(archforge_diagram::DIAGRAM)).unwrap();
    assert_eq!(st.get(d, archforge_diagram::diagram::KIND).unwrap().as_str(), Some(archforge_uml::CLASS_DIAGRAM));
    assert_eq!(st.list(d, archforge_diagram::diagram::NODE).unwrap().len(), 1);
}

#[test]
fn an_er_project_makes_a_class_diagram_beside_its_er_diagrams_and_an_agent_makes_one_too() {
    let (mut h, _customer, er_diagram) = diagram_harness();
    let at = rect_of(&h, "workspace.tabs.add").center();
    click(&mut h, at);
    assert_eq!(h.state().diagrams.new.as_ref().unwrap().kind, archforge_er::DIAGRAM_KIND, "an ER project starts at ER");
    let at = rect_of(&h, "workspace.new-diagram.type.uml.class").center();
    click(&mut h, at);
    let at = rect_of(&h, "workspace.new-diagram.continue").center();
    click(&mut h, at);
    h.state_mut().diagrams.new.as_mut().unwrap().name = "Domain".into();
    let at = rect_of(&h, "workspace.new-diagram.create").center();
    click(&mut h, at);
    assert_eq!(class_diagram_shown(&h).0, archforge_uml::CLASS_DIAGRAM);
    assert_eq!(h.state().canvas.tabs.len(), 2, "beside the ER diagram's tab");
    assert!(h.state().canvas.tabs.contains(&archforge_mof::Uuid::parse(&er_diagram).unwrap()));
    // An agent, through the control channel's commands, as its MCP tools call them.
    let mut call = |command: &str, params: serde_json::Value| {
        let out = crate::control::answer(h.state_mut(), "engine.execute", &serde_json::json!({ "command": command, "params": params }))
            .unwrap_or_else(|e| panic!("{command}: {e}"));
        out["result"]["id"].as_str().unwrap_or_default().to_string()
    };
    let pkg = call("uml.package.add", serde_json::json!({ "name": "Billing" }));
    let d = call("diagram.add", serde_json::json!({ "kind": "uml.class", "element": pkg, "name": "Billing" }));
    let invoice = call("uml.class.add", serde_json::json!({ "package": pkg, "name": "Invoice" }));
    call("diagram.place", serde_json::json!({ "diagram": d, "element": invoice, "x": 100, "y": 100 }));
    let st = h.state().session.as_ref().unwrap().doc();
    let d = st.by_uuid(archforge_mof::Uuid::parse(&d).unwrap()).expect("the agent's class diagram");
    assert_eq!(st.list(d, archforge_diagram::diagram::NODE).unwrap().len(), 1);
}

/// The sample class model open on its class diagram, and the edge of its association `name`.
fn read_class_diagram(name: &str) -> (Harness<'static, Shell>, archforge_mof::Obj, archforge_mof::Obj) {
    let mut h = workspace_harness(ThemeKind::Light, egui::vec2(1600.0, 1000.0));
    crate::uml_ui::open_sample(h.state_mut()).unwrap();
    h.run();
    let st = h.state().session.as_ref().unwrap().doc();
    let d = st.by_uuid(h.state().canvas.active.unwrap()).unwrap();
    let a = st.alive().find(|o| st.class_of(*o).ok() == Some(archforge_uml::ASSOCIATION) && archforge_core::name_of(st, *o) == name).unwrap();
    let e = archforge_diagram::views_of(st, a).1[0];
    (h, d, e)
}

/// Whether the last frame painted a path in the accent colour.
fn painted_accent(h: &Harness<'static, Shell>) -> bool {
    let accent = crate::ux::palette(false).accent;
    fn walk(s: &egui::Shape, accent: egui::Color32) -> bool {
        match s {
            egui::Shape::Path(p) => p.stroke.color == egui::epaint::ColorMode::Solid(accent),
            egui::Shape::Vec(v) => v.iter().any(|s| walk(s, accent)),
            _ => false,
        }
    }
    h.output().shapes.iter().any(|c| walk(&c.shape, accent))
}

#[test]
fn a_class_diagram_draws_every_line_kind_and_its_lines_highlight_and_their_texts_and_segments_drag() {
    let (mut h, d, e) = read_class_diagram("paid by");
    let st = h.state().session.as_ref().unwrap().doc();
    // Every line kind is on the diagram, each drawn as its notation describes it.
    let lines: Vec<archforge_diagram::figure::Line> = st
        .list(d, archforge_diagram::diagram::EDGE)
        .unwrap()
        .iter()
        .filter_map(archforge_mof::Value::as_ref)
        .filter_map(|edge| st.get(edge, archforge_diagram::edge::ELEMENT).ok()?.as_ref())
        .filter_map(|el| archforge_uml::figures::line(st, el))
        .collect();
    use archforge_diagram::figure::EndMark as M;
    let marks: Vec<[M; 2]> = lines.iter().map(|l| [l.ends[0].mark, l.ends[1].mark]).collect();
    for kind in [M::OpenArrow, M::FilledDiamond, M::HollowDiamond, M::Triangle] {
        assert!(marks.iter().any(|m| m.contains(&kind)), "{kind:?} in {marks:?}");
    }
    assert!(marks.contains(&[M::OpenArrow, M::OpenArrow]), "navigable both ways: an arrow at each end");
    assert!(lines.iter().any(|l| l.dashed), "the dependency is dashed");
    let texts = painted(&h);
    for t in ["CLASS", "Payment", "+ amount : Money", "+ authorise() : Boolean", "+ price : Money [0..1]", "paid by", "1..*", "0..1", "lines"] {
        assert!(texts.iter().any(|x| x == t), "{t} is drawn: {texts:?}");
    }
    // The hovered line turns to the accent.
    assert!(!painted_accent(&h), "nothing is selected or hovered yet");
    let route = |h: &Harness<'static, Shell>| archforge_diagram::Grid::build(h.state().session.as_ref().unwrap().doc(), d).line(e).unwrap().to_vec();
    let before = route(&h);
    assert!(before.len() >= 3, "a right-angled route: {before:?}");
    let view = crate::canvas::View { origin: rect_of(&h, "workspace.canvas").min, pan: h.state().canvas.pan, zoom: h.state().canvas.zoom };
    let middle = view.to_screen((before[1].0 + before[2].0) / 2.0, (before[1].1 + before[2].1) / 2.0);
    h.event(egui::Event::PointerMoved(middle));
    h.run();
    assert!(painted_accent(&h), "the hovered line is highlighted");
    // A multiplicity text drags aside and stays where it was let go.
    let edge = h.state().session.as_ref().unwrap().doc().uuid(e).unwrap();
    let text = h.state().canvas.ends.iter().find(|t| t.edge == edge && t.end == 1).cloned().expect("the line's end text is drawn");
    let to = text.rect.center() + egui::vec2(30.0, 30.0);
    drag(&mut h, text.rect.center(), to);
    h.run();
    let moved = h.state().canvas.ends.iter().find(|t| t.edge == edge && t.end == 1).cloned().unwrap();
    assert!((moved.rect.center() - to).length() < 2.0, "drawn where it was let go: {:?} {to:?}", moved.rect.center());
    // A segment slides across.
    let level = (before[1].1 - before[2].1).abs() < 1e-6;
    let shift = if level { egui::vec2(0.0, -40.0) } else { egui::vec2(-40.0, 0.0) };
    let middle = view.to_screen((before[1].0 + before[2].0) / 2.0, (before[1].1 + before[2].1) / 2.0);
    drag(&mut h, middle, middle + shift * view.zoom);
    let after = route(&h);
    let slid = if level { (after[1].1 - (before[1].1 - 40.0)).abs() < 1.0 } else { (after[1].0 - (before[1].0 - 40.0)).abs() < 1.0 };
    assert!(slid, "{before:?} → {after:?}");
}

/// The sample class model open with `class` selected and Properties showing it; gives its id.
fn class_properties(class: &str) -> (Harness<'static, Shell>, archforge_mof::Uuid) {
    let mut h = workspace_harness(ThemeKind::Light, egui::vec2(1600.0, 1000.0));
    crate::uml_ui::open_sample(h.state_mut()).unwrap();
    let st = h.state().session.as_ref().unwrap().doc();
    let c = st.alive().find(|o| st.class_of(*o).ok() == Some(archforge_uml::CLASS) && archforge_core::name_of(st, *o) == class).unwrap();
    let id = st.uuid(c).unwrap();
    h.state_mut().session.as_mut().unwrap().execute("view.select", &serde_json::json!({ "ids": [id.to_string()] })).unwrap();
    h.state_mut().state.show_panel(crate::state::Panel::Properties);
    h.run();
    (h, id)
}

/// A class's attributes or operations as its card lists them.
fn member_rows(h: &Harness<'static, Shell>, class: archforge_mof::Uuid, operations: bool) -> Vec<String> {
    let st = h.state().session.as_ref().unwrap().doc();
    let c = st.by_uuid(class).unwrap();
    if operations {
        archforge_uml::members::operations(st, c).into_iter().map(|o| archforge_uml::figures::operation_text(st, o)).collect()
    } else {
        archforge_uml::members::attributes(st, c).into_iter().map(|a| archforge_uml::figures::attribute_text(st, a)).collect()
    }
}

/// Picks the type labelled `label` from the open editor's type select `id`.
fn pick_type(h: &mut Harness<'static, Shell>, id: &str, label: &str) {
    let at = rect_of(h, id).center();
    click(h, at);
    let i = crate::uml_panel::type_choices(h.state().session.as_ref().unwrap().doc(), None).iter().position(|(l, _)| l == label).expect(label);
    let at = rect_of(h, &format!("{id}.{i}")).center();
    click(h, at);
}

/// Clicks the field `id` and types `text` into it.
fn type_into(h: &mut Harness<'static, Shell>, id: &str, text: &str) {
    let at = rect_of(h, id).center();
    click(h, at);
    h.event(egui::Event::Text(text.into()));
    h.run();
}

#[test]
fn a_class_takes_attributes_in_properties_typed_checked_moved_and_removed_each_one_undo_step() {
    let (mut h, customer) = class_properties("Customer");
    let texts = painted(&h);
    assert!(texts.iter().any(|t| t == "Attributes · 2") && texts.iter().any(|t| t == "Operations · 1"), "{texts:?}");
    assert_eq!(member_rows(&h, customer, false), ["+ id : Integer", "- email : String"]);
    // + opens the editor with the name taking the keyboard; a built-in type makes the Types package.
    let at = rect_of(&h, "workspace.properties.attributes.add").center();
    click(&mut h, at);
    assert!(h.state().panels.member.as_ref().is_some_and(|e| e.target.is_none()), "the editor is open for a new attribute");
    h.event(egui::Event::Text("rating".into()));
    h.run();
    pick_type(&mut h, "workspace.properties.member.type", "Real");
    type_into(&mut h, "workspace.properties.member.multiplicity", "0..1");
    let at = rect_of(&h, "workspace.properties.member.apply").center();
    click(&mut h, at);
    assert!(h.state().panels.member.is_none(), "{:?}", h.state().panels.member);
    assert_eq!(member_rows(&h, customer, false), ["+ id : Integer", "- email : String", "+ rating : Real [0..1]"]);
    let st = h.state().session.as_ref().unwrap().doc();
    assert!(
        archforge_uml::commands::all_packages(st).iter().any(|p| archforge_core::name_of(st, *p) == archforge_uml::members::TYPES),
        "Real is kept in Types"
    );
    let root = archforge_uml::commands::root_package(st).expect("the root package");
    assert!(
        archforge_uml::commands::subpackages(st, root).iter().any(|p| archforge_core::name_of(st, *p) == archforge_uml::members::TYPES),
        "Types sits in the root package"
    );
    h.run();
    assert!(painted(&h).iter().any(|t| t == "+ rating : Real [0..1]"), "the card and the row show it");
    // One undo step takes it back, redo brings it again.
    h.state_mut().session.as_mut().unwrap().undo().unwrap();
    assert_eq!(member_rows(&h, customer, false).len(), 2);
    h.state_mut().session.as_mut().unwrap().redo().unwrap();
    h.run();
    assert_eq!(member_rows(&h, customer, false).len(), 3);
    // A click on a row selects the attribute; Properties stays the class's, the row marked.
    let st = h.state().session.as_ref().unwrap().doc();
    let rating = st.uuid(archforge_uml::members::attributes(st, st.by_uuid(customer).unwrap())[2]).unwrap();
    let row = format!("workspace.properties.attribute.{rating}");
    let at = rect_of(&h, &row).left_center() + egui::vec2(20.0, 0.0);
    click(&mut h, at);
    assert_eq!(crate::panels::selected_id(h.state()), Some(rating));
    assert!(painted(&h).iter().any(|t| t == "Attributes · 3"), "the class's panel shows for its attribute");
    // Its edit button opens the editor in its place; a multiplicity that does not read is refused.
    let at = rect_of(&h, &format!("{row}.edit")).center();
    click(&mut h, at);
    assert_eq!(h.state().panels.member.as_ref().and_then(|e| e.target), Some(rating));
    assert_eq!(h.state().panels.member.as_ref().unwrap().multiplicity, "0..1");
    h.state_mut().panels.member.as_mut().unwrap().multiplicity = "3..1".into();
    let at = rect_of(&h, "workspace.properties.member.apply").center();
    click(&mut h, at);
    let refused = h.state().panels.member.as_ref().and_then(|e| e.refused.clone()).expect("refused");
    assert_eq!(refused, "The upper bound must be at least 3.", "said in the user's words");
    assert_eq!(h.state().panels.member.as_ref().and_then(|e| e.refused_at), Some("multiplicity"), "under its field");
    assert_eq!(member_rows(&h, customer, false)[2], "+ rating : Real [0..1]", "nothing changed");
    // Private and static, applied.
    h.state_mut().panels.member.as_mut().unwrap().multiplicity = "1..*".into();
    let at = rect_of(&h, "workspace.properties.member.visibility").center();
    click(&mut h, at);
    let at = rect_of(&h, "workspace.properties.member.visibility.1").center();
    click(&mut h, at);
    let at = rect_of(&h, "workspace.properties.member.static").center();
    click(&mut h, at);
    let at = rect_of(&h, "workspace.properties.member.apply").center();
    click(&mut h, at);
    assert_eq!(member_rows(&h, customer, false)[2], "- rating : Real [1..*]");
    let st = h.state().session.as_ref().unwrap().doc();
    assert_eq!(st.get(st.by_uuid(rating).unwrap(), archforge_uml::feature::IS_STATIC).unwrap().as_bool(), Some(true));
    // Moved up past email, then removed; undo brings it back where it was.
    let at = rect_of(&h, &format!("{row}.edit")).center();
    click(&mut h, at);
    let at = rect_of(&h, "workspace.properties.member.up").center();
    click(&mut h, at);
    assert_eq!(member_rows(&h, customer, false), ["+ id : Integer", "- rating : Real [1..*]", "- email : String"]);
    let at = rect_of(&h, "workspace.properties.member.remove").center();
    click(&mut h, at);
    assert_eq!(member_rows(&h, customer, false), ["+ id : Integer", "- email : String"]);
    assert!(h.state().panels.member.is_none());
    h.state_mut().session.as_mut().unwrap().undo().unwrap();
    assert_eq!(member_rows(&h, customer, false), ["+ id : Integer", "- rating : Real [1..*]", "- email : String"]);
}

#[test]
fn a_class_takes_operations_with_parameters_and_turns_abstract_in_properties() {
    let (mut h, payment) = class_properties("CardPayment");
    // The class turns abstract: its name slants on its card.
    let at = rect_of(&h, "workspace.properties.class.abstract").center();
    click(&mut h, at);
    let st = h.state().session.as_ref().unwrap().doc();
    assert_eq!(st.get(st.by_uuid(payment).unwrap(), archforge_uml::class::IS_ABSTRACT).unwrap().as_bool(), Some(true));
    // An operation with a parameter typed by a class of the model and a return type.
    let at = rect_of(&h, "workspace.properties.operations.add").center();
    click(&mut h, at);
    h.event(egui::Event::Text("refund".into()));
    h.run();
    pick_type(&mut h, "workspace.properties.member.type", "Boolean");
    let at = rect_of(&h, "workspace.properties.member.parameter.add").center();
    click(&mut h, at);
    type_into(&mut h, "workspace.properties.member.parameter.0.name", "to");
    pick_type(&mut h, "workspace.properties.member.parameter.0.type", "Customer");
    let at = rect_of(&h, "workspace.properties.member.abstract").center();
    click(&mut h, at);
    let at = rect_of(&h, "workspace.properties.member.parameter.add").center();
    click(&mut h, at);
    type_into(&mut h, "workspace.properties.member.parameter.1.name", "times");
    // The editor grew with its parameters past the body's foot: the body scrolls to the rest.
    let scroll = |h: &mut Harness<'static, Shell>| {
        let body = h.state().panels.body.unwrap();
        h.event(egui::Event::PointerMoved(body.center()));
        h.event(egui::Event::MouseWheel {
            unit: egui::MouseWheelUnit::Point,
            delta: egui::vec2(0.0, -400.0),
            modifiers: egui::Modifiers::NONE,
            phase: egui::TouchPhase::Move,
            source: egui::MouseWheelSource::Wheel,
        });
        h.run_steps(30);
    };
    scroll(&mut h);
    type_into(&mut h, "workspace.properties.member.parameter.1.multiplicity", "0..*");
    scroll(&mut h);
    let at = rect_of(&h, "workspace.properties.member.apply").center();
    click(&mut h, at);
    assert!(h.state().panels.member.is_none(), "{:?}", h.state().panels.member);
    assert_eq!(member_rows(&h, payment, true), ["+ refund(to : Customer, times) : Boolean"]);
    let st = h.state().session.as_ref().unwrap().doc();
    let op = archforge_uml::members::operations(st, st.by_uuid(payment).unwrap())[0];
    assert_eq!(st.get(op, archforge_uml::behavioral_feature::IS_ABSTRACT).unwrap().as_bool(), Some(true));
    assert_eq!(archforge_uml::figures::multiplicity(st, archforge_uml::members::parameters(st, op).0[1]), "*");
    // Opened again it holds what it was given; a parameter's ✕ drops it.
    let op_id = st.uuid(op).unwrap();
    let at = rect_of(&h, &format!("workspace.properties.operation.{op_id}.edit")).center();
    click(&mut h, at);
    let edit = h.state().panels.member.clone().unwrap();
    assert_eq!((edit.name.as_str(), edit.params.len(), edit.is_abstract), ("refund", 2, true));
    // The built-in Boolean, by its name, which the commands resolve to the one in Types.
    assert_eq!(edit.ty, "Boolean");
    let at = rect_of(&h, "workspace.properties.member.parameter.1.remove").center();
    click(&mut h, at);
    let at = rect_of(&h, "workspace.properties.member.apply").center();
    click(&mut h, at);
    assert_eq!(member_rows(&h, payment, true), ["+ refund(to : Customer) : Boolean"]);
}

/// A class diagram of the package Orders, two deep under the root (root › Fulfilment › Orders), at
/// 100 %: the class Order (`number : Integer`, `total : Money`, `pay() : Boolean`) at (80, 80) and
/// the enumeration OrderStatus (Placed, Paid, Shipped) at (480, 80). Gives the harness, Order's id
/// and OrderStatus's id.
fn nested_orders(theme: ThemeKind) -> (Harness<'static, Shell>, archforge_mof::Uuid, archforge_mof::Uuid) {
    let mut h = workspace_harness(theme, egui::vec2(1600.0, 1000.0));
    let run = |h: &mut Harness<'static, Shell>, command: &str, params: serde_json::Value| {
        let out = h.state_mut().session.as_mut().unwrap().execute(command, &params).unwrap_or_else(|e| panic!("{command}: {e}"));
        out.value["id"].as_str().map(|i| archforge_mof::Uuid::parse(i).unwrap())
    };
    let fulfilment = run(&mut h, "uml.package.add", serde_json::json!({ "name": "Fulfilment" })).unwrap();
    let orders = run(&mut h, "uml.package.add", serde_json::json!({ "name": "Orders", "parent": fulfilment.to_string() })).unwrap();
    let d = run(&mut h, "diagram.add", serde_json::json!({ "kind": "uml.class", "element": orders.to_string(), "name": "Orders" })).unwrap();
    let money = run(&mut h, "uml.data-type.add", serde_json::json!({ "package": orders.to_string(), "name": "Money" })).unwrap();
    let order = run(&mut h, "uml.class.add", serde_json::json!({ "package": orders.to_string(), "name": "Order" })).unwrap();
    run(&mut h, "uml.attribute.add", serde_json::json!({ "class": order.to_string(), "name": "number", "type": "Integer" }));
    run(&mut h, "uml.attribute.add", serde_json::json!({ "class": order.to_string(), "name": "total", "type": money.to_string() }));
    run(&mut h, "uml.operation.add", serde_json::json!({ "class": order.to_string(), "name": "pay", "returns": "Boolean" }));
    let status = run(&mut h, "uml.enumeration.add", serde_json::json!({ "package": orders.to_string(), "name": "OrderStatus" })).unwrap();
    for (element, x, height) in [(order, 80, crate::uml_ui::members_height(2, 1)), (status, 480, crate::uml_ui::literals_height(3))] {
        let place = serde_json::json!({ "diagram": d.to_string(), "element": element.to_string(), "x": x, "y": 80, "width": 280, "height": height });
        run(&mut h, "diagram.place", place);
    }
    crate::uml_ui::put_literals(h.state_mut(), status, &["Placed", "Paid", "Shipped"]).unwrap();
    crate::canvas::open(h.state_mut(), d);
    h.run();
    let shell = h.state_mut();
    shell.canvas.fit_pending = false;
    shell.canvas.zoom = 1.0;
    shell.canvas.pan = egui::Vec2::ZERO;
    h.run();
    (h, order, status)
}

/// Every text the last frame painted, with the box its galley took.
fn text_boxes(h: &Harness<'static, Shell>) -> Vec<(String, egui::Rect)> {
    fn walk(s: &egui::Shape, out: &mut Vec<(String, egui::Rect)>) {
        match s {
            egui::Shape::Text(t) => out.push((t.galley.text().to_string(), egui::Rect::from_min_size(t.pos, t.galley.size()))),
            egui::Shape::Vec(v) => v.iter().for_each(|s| walk(s, out)),
            _ => {}
        }
    }
    let mut out = Vec::new();
    h.output().shapes.iter().for_each(|c| walk(&c.shape, &mut out));
    out
}

/// Every rectangle the last frame painted, with its fill and its stroke's colour.
fn rect_shapes(h: &Harness<'static, Shell>) -> Vec<(egui::Rect, egui::Color32, egui::Color32)> {
    fn walk(s: &egui::Shape, out: &mut Vec<(egui::Rect, egui::Color32, egui::Color32)>) {
        match s {
            egui::Shape::Rect(r) => out.push((r.rect, r.fill, r.stroke.color)),
            egui::Shape::Vec(v) => v.iter().for_each(|s| walk(s, out)),
            _ => {}
        }
    }
    let mut out = Vec::new();
    h.output().shapes.iter().for_each(|c| walk(&c.shape, &mut out));
    out
}

/// Properties' Package select of a classifier in a nested package shows the package's own name:
/// a path too long for the field is cut from its front (`… › Orders`), never from its end, and the
/// whole path is its accessible name and its tooltip (AR-191); in light and dark.
#[test]
fn a_package_select_cuts_a_long_path_from_its_front_so_the_package_name_shows() {
    for theme in [ThemeKind::Light, ThemeKind::Dark] {
        let (mut h, order, _) = nested_orders(theme);
        h.state_mut().session.as_mut().unwrap().execute("view.select", &serde_json::json!({ "ids": [order.to_string()] })).unwrap();
        h.state_mut().state.show_panel(crate::state::Panel::Properties);
        h.run();
        let path = {
            let st = h.state().session.as_ref().unwrap().doc();
            let root = archforge_core::name_of(st, archforge_uml::commands::root_package(st).unwrap());
            format!("{root} › Fulfilment › Orders")
        };
        let field = rect_of(&h, "workspace.properties.class.owner");
        let shown: Vec<String> = text_boxes(&h).into_iter().filter(|(_, r)| field.contains(r.center())).map(|(t, _)| t).collect();
        assert_eq!(shown, ["… › Orders"], "{theme:?}: the package's own name, its path's front folded");
        {
            use egui_kittest::kittest::Queryable;
            assert!(h.query_by_label(&format!("Owner: {path}")).is_some(), "the whole path is its accessible name");
        }
        // Hovered long enough, its tooltip says the whole path.
        h.event(egui::Event::PointerMoved(field.center()));
        for _ in 0..90 {
            h.step();
        }
        assert!(painted(&h).contains(&path), "{theme:?}: the tooltip says {path:?} in {:?}", painted(&h));
        // A package whose own name holds the separator is one part: the fold never splits it.
        let orders = {
            let st = h.state().session.as_ref().unwrap().doc();
            st.uuid(archforge_uml::commands::package_of(st, st.by_uuid(order).unwrap()).unwrap()).unwrap()
        };
        let renamed = serde_json::json!({ "package": orders.to_string(), "name": "Orders › EU" });
        h.state_mut().session.as_mut().unwrap().execute("uml.package.rename", &renamed).unwrap();
        h.event(egui::Event::PointerMoved(egui::pos2(5.0, 5.0)));
        h.run();
        let shown: Vec<String> = text_boxes(&h).into_iter().filter(|(_, r)| field.contains(r.center())).map(|(t, _)| t).collect();
        assert_eq!(shown, ["Orders › EU"], "{theme:?}: the name kept whole, never folded at its own › into `… › EU`");
    }
    // The cut keeps the last part: whole, else its front parts folded, else the last part alone,
    // which the field cuts at its end as it cuts any name. The parts are given, so a name holding
    // the separator stays one part.
    let fits = |room: usize| move |t: &str| t.chars().count() <= room;
    let cut = |parts: &[&str], room: usize| crate::ux::cut_front(parts, " › ", fits(room));
    assert_eq!(cut(&["Commerce", "Orders"], 40), ("Commerce › Orders".to_string(), false));
    assert_eq!(cut(&["Commerce", "Fulfilment", "Orders"], 23), ("… › Fulfilment › Orders".to_string(), true));
    assert_eq!(cut(&["Commerce", "Fulfilment", "Orders"], 12), ("… › Orders".to_string(), true));
    assert_eq!(cut(&["Commerce", "Orders"], 4), ("Orders".to_string(), true));
    assert_eq!(cut(&["Commerce platform"], 4), ("Commerce platform".to_string(), true));
    assert_eq!(cut(&["Commerce", "Orders › EU"], 15), ("… › Orders › EU".to_string(), true), "one part, though it holds the separator");
    assert_eq!(cut(&["Commerce", "Orders › EU"], 8), ("Orders › EU".to_string(), true), "never folded inside a name");
}

/// The index of `package` among every package, as Properties' Package menu lists them.
fn st_index(st: &archforge_mof::Store, package: archforge_mof::Obj) -> usize {
    archforge_uml::commands::all_packages(st).iter().position(|p| *p == package).unwrap()
}

/// A package's path names every ancestor up to the root, however deep (here 40 packages, past
/// any fixed cap and wider than the window): the Package field and its menu's row fold it from the
/// front, its last packages showing, and say it whole on hover. A walk that comes back on itself,
/// as a damaged file's could, ends with each element named once (AR-191).
#[test]
fn a_package_path_names_every_ancestor_and_a_cycle_ends() {
    let mut h = workspace_harness(ThemeKind::Light, egui::vec2(1600.0, 1000.0));
    let mut parent: Option<String> = None;
    for i in 1..=40 {
        let mut params = serde_json::json!({ "name": format!("Package {i}") });
        if let Some(p) = &parent {
            params["parent"] = serde_json::json!(p);
        }
        let out = h.state_mut().session.as_mut().unwrap().execute("uml.package.add", &params).unwrap();
        parent = out.value["id"].as_str().map(String::from);
    }
    let deepest_id = parent.unwrap();
    let st = h.state().session.as_ref().unwrap().doc();
    let deepest = st.by_uuid(archforge_mof::Uuid::parse(&deepest_id).unwrap()).unwrap();
    let parts = crate::uml_panel::package_parts(st, deepest);
    let root = archforge_core::name_of(st, archforge_uml::commands::root_package(st).unwrap());
    assert_eq!(parts.len(), 41, "the root and all 40: {parts:?}");
    assert_eq!((parts[0].as_str(), parts[1].as_str(), parts[40].as_str()), (root.as_str(), "Package 1", "Package 40"));
    let whole = parts.join(" › ");
    let row_of = st_index(st, deepest);
    // A class in the deepest package: Properties' Package field and its menu's row both fold the
    // path from its front, the last packages showing, and say it whole on hover.
    let class =
        h.state_mut().session.as_mut().unwrap().execute("uml.class.add", &serde_json::json!({ "package": deepest_id, "name": "Deep" })).unwrap();
    let class = class.value["id"].as_str().unwrap().to_string();
    h.state_mut().session.as_mut().unwrap().execute("view.select", &serde_json::json!({ "ids": [class] })).unwrap();
    h.state_mut().state.show_panel(crate::state::Panel::Properties);
    h.run();
    let field = rect_of(&h, "workspace.properties.class.owner");
    let shown: Vec<String> = text_boxes(&h).into_iter().filter(|(_, r)| field.contains(r.center())).map(|(t, _)| t).collect();
    let [shown] = shown.as_slice() else { panic!("one text in the field: {shown:?}") };
    assert!(shown.ends_with("Package 40") && !shown.starts_with(root.as_str()), "the field keeps the package's own name: {shown:?}");
    click(&mut h, field.center());
    assert_eq!(h.state().panels.menu, Some(crate::panels::Menu::ClassOwner));
    for _ in 0..=row_of {
        key(&mut h, egui::Key::ArrowDown, egui::Modifiers::NONE);
    }
    let row = rect_of(&h, &format!("workspace.properties.class.owner.{row_of}"));
    // The row's text, over what the window shows under the menu.
    let drawn: Vec<String> = text_boxes(&h).into_iter().filter(|(t, r)| row.contains(r.center()) && t.contains("Package")).map(|(t, _)| t).collect();
    let [drawn] = drawn.as_slice() else { panic!("one path in the row: {drawn:?}") };
    assert!(
        drawn.starts_with("… › ") && drawn.ends_with(" › Package 38 › Package 39 › Package 40") && !drawn.contains(root.as_str()),
        "the row's end shows: {drawn:?}"
    );
    assert!(!drawn.ends_with('…'), "never cut at its end: {drawn:?}");
    h.event(egui::Event::PointerMoved(row.center()));
    for _ in 0..90 {
        h.step();
    }
    assert!(painted(&h).contains(&whole), "the row's tooltip says the whole path");
    // A cycle, which the model refuses to make but a damaged file could hold, and a loop on itself.
    let name = |n: u32| n.to_string();
    assert_eq!(crate::uml_panel::path_parts(0_u32, |n| Some((n + 1) % 3), name), ["2", "1", "0"]);
    assert_eq!(crate::uml_panel::path_parts(7_u32, Some, name), ["7"]);
    assert_eq!(crate::uml_panel::path_parts(5_u32, |n| n.checked_sub(1), name), ["0", "1", "2", "3", "4", "5"]);
}

/// Every compartment of a class's card is padded as the card is (AR-191): the last attribute's
/// text ends as far over the dividing line as the last operation's over the card's foot, and the
/// first operation starts as far under that line as the first attribute under the header's; a new
/// class's default size holds a row in each, and a card one unit short says the row it hides; in
/// light and dark.
#[test]
fn a_class_cards_compartments_are_padded_so_no_row_sits_on_a_dividing_line() {
    for theme in [ThemeKind::Light, ThemeKind::Dark] {
        let (h, order, _) = nested_orders(theme);
        let card = rect_of(&h, &format!("workspace.canvas.node.{}", node_of(&h, order)));
        let boxes = text_boxes(&h);
        let row =
            |t: &str| boxes.iter().find(|(s, r)| s == t && card.contains(r.center())).map(|(_, r)| *r).unwrap_or_else(|| panic!("{t} on the card"));
        let (first_attribute, last_attribute, operation) = (row("+ number : Integer"), row("+ total : Money"), row("+ pay() : Boolean"));
        // The lines across the card: the header's, then the one between its compartments.
        let mut lines: Vec<f32> = rect_shapes(&h)
            .into_iter()
            .filter(|(r, _, _)| (r.height() - 1.0).abs() < 0.01 && (r.width() - card.width()).abs() < 0.5 && card.contains(r.center()))
            .map(|(r, _, _)| r.top())
            .collect();
        lines.sort_by(f32::total_cmp);
        let [header, divider] = lines[..] else { panic!("{theme:?}: two lines across the card, not {lines:?}") };
        assert!(divider > last_attribute.bottom() + 8.0, "{theme:?}: the line {divider} clear of the row ending at {}", last_attribute.bottom());
        let near = |a: f32, b: f32| (a - b).abs() < 0.5;
        assert!(near(divider - last_attribute.bottom(), card.bottom() - operation.bottom()), "{theme:?}: a compartment's foot is the card's");
        assert!(near(operation.top() - divider, first_attribute.top() - header), "{theme:?}: a compartment's head is the first one's");
    }
    // A new class shows a row in each compartment at its default size; the card height grows by
    // a pitch for each row, and made too short for its last row it counts the rows it hides, the
    // last one that fits saying so.
    assert_eq!(crate::uml_ui::members_height(1, 1), archforge_uml::CLASS_SIZE.1);
    assert_eq!(crate::uml_ui::members_height(2, 1) - crate::uml_ui::members_height(1, 1), f64::from(crate::canvas::ENTITY_ROW));
    let (mut h, order, _) = nested_orders(ThemeKind::Light);
    let node = node_of(&h, order);
    let height = crate::uml_ui::members_height(2, 1) - 11.0;
    h.state_mut().session.as_mut().unwrap().execute("diagram.resize", &serde_json::json!({ "node": node, "width": 280, "height": height })).unwrap();
    h.run();
    let texts = painted(&h);
    assert!(texts.iter().any(|t| t == "+ 2 more members") && texts.iter().any(|t| t == "+ number : Integer"), "{texts:?}");
}

/// Every level line segment the last frame painted: its left and right ends, its height, its
/// thickness and its colour.
fn level_lines(h: &Harness<'static, Shell>) -> Vec<(f32, f32, f32, f32, egui::Color32)> {
    fn walk(s: &egui::Shape, out: &mut Vec<(f32, f32, f32, f32, egui::Color32)>) {
        match s {
            egui::Shape::LineSegment { points: [a, b], stroke } if (a.y - b.y).abs() < 0.01 => {
                out.push((a.x.min(b.x), a.x.max(b.x), a.y, stroke.width, stroke.color));
            }
            egui::Shape::Vec(v) => v.iter().for_each(|s| walk(s, out)),
            _ => {}
        }
    }
    let mut out = Vec::new();
    h.output().shapes.iter().for_each(|c| walk(&c.shape, &mut out));
    out
}

/// A static member's row is underlined on its card (AR-136): the line runs under the row's text,
/// from where it starts to no further than it ends, in the text's ink, at least a pixel thick, in
/// light and dark and at the detail zoom, 100 % and 200 %; a static abstract operation is
/// underlined and slanted; a plain row has none; Properties' rows read as the card's; a row cut
/// short by a narrow card keeps its underline inside the card; clearing Static takes it away.
#[test]
fn a_static_members_row_is_underlined_on_its_card() {
    for theme in [ThemeKind::Light, ThemeKind::Dark] {
        let (mut h, order, _) = nested_orders(theme);
        let p = crate::ux::palette(theme == ThemeKind::Dark);
        let (number, pay) = {
            let st = h.state().session.as_ref().unwrap().doc();
            let o = st.by_uuid(order).unwrap();
            let number = st.uuid(archforge_uml::members::attributes(st, o)[0]).unwrap();
            let pay = st.uuid(archforge_uml::members::operations(st, o)[0]).unwrap();
            (number, pay)
        };
        let session = |h: &mut Harness<'static, Shell>, command: &str, params: serde_json::Value| {
            h.state_mut().session.as_mut().unwrap().execute(command, &params).unwrap_or_else(|e| panic!("{command}: {e}"));
            h.run();
        };
        session(&mut h, "uml.attribute.set", serde_json::json!({ "attribute": number.to_string(), "static": true }));
        let static_abstract =
            serde_json::json!({ "operation": pay.to_string(), "name": "pay", "returns": "Boolean", "static": true, "abstract": true });
        session(&mut h, "uml.operation.set", static_abstract);
        // The underline under the row `text` within `area`, when there is one.
        let under = |h: &Harness<'static, Shell>, area: egui::Rect, text: &str| {
            let (_, r) =
                text_boxes(h).into_iter().find(|(t, r)| t == text && area.contains(r.center())).unwrap_or_else(|| panic!("{text} in {area:?}"));
            level_lines(h).into_iter().find(|(left, right, y, _, _)| {
                (left - r.left()).abs() < 1.0 && *right <= r.right() + 0.5 && *right > r.center().x && *y > r.center().y && *y < r.bottom()
            })
        };
        for zoom in [crate::canvas::DETAIL_ZOOM, 1.0, 2.0] {
            h.state_mut().canvas.zoom = zoom;
            h.run();
            let card = rect_of(&h, &format!("workspace.canvas.node.{}", node_of(&h, order)));
            for row in ["+ number : Integer", "+ pay() : Boolean"] {
                let (_, _, _, width, colour) = under(&h, card, row).unwrap_or_else(|| panic!("{theme:?} at {zoom}: {row} is underlined"));
                assert_eq!(colour, p.text, "{theme:?} at {zoom}: {row} in the text's ink");
                assert!(width >= 1.0, "{theme:?} at {zoom}: {row} at least a pixel thick");
            }
            assert!(under(&h, card, "+ total : Money").is_none(), "{theme:?} at {zoom}: a plain row has no underline");
        }
        h.state_mut().canvas.zoom = 1.0;
        h.run();
        // Properties' rows read as the card's.
        session(&mut h, "view.select", serde_json::json!({ "ids": [order.to_string()] }));
        h.state_mut().state.show_panel(crate::state::Panel::Properties);
        h.run();
        let row = rect_of(&h, &format!("workspace.properties.attribute.{number}"));
        assert!(under(&h, row, "+ number : Integer").is_some(), "{theme:?}: Properties' row is underlined");
        let row = rect_of(&h, &format!("workspace.properties.operation.{pay}"));
        assert!(under(&h, row, "+ pay() : Boolean").is_some(), "{theme:?}: Properties' operation row is underlined");
        // A narrow card cuts the row short: its underline stays inside the card.
        let node = node_of(&h, order);
        let height = crate::uml_ui::members_height(2, 1);
        session(&mut h, "diagram.resize", serde_json::json!({ "node": node, "width": 120, "height": height }));
        let card = rect_of(&h, &format!("workspace.canvas.node.{node}"));
        let (_, right, _, _, _) = under(&h, card, "+ number : Integer").unwrap_or_else(|| panic!("{theme:?}: the cut row is underlined"));
        assert!(right < card.right(), "{theme:?}: the underline {right} ends inside the card {card:?}");
        // Static cleared: the underline goes; undone, it is back.
        session(&mut h, "uml.attribute.set", serde_json::json!({ "attribute": number.to_string(), "static": false }));
        let card = rect_of(&h, &format!("workspace.canvas.node.{node}"));
        assert!(under(&h, card, "+ number : Integer").is_none(), "{theme:?}: cleared, no underline");
        h.state_mut().session.as_mut().unwrap().undo().unwrap();
        h.run();
        assert!(under(&h, card, "+ number : Integer").is_some(), "{theme:?}: undone, underlined again");
    }
}

/// A literal's draft row is spaced as an attribute's and an operation's (AR-191): each ring takes
/// its row's pitch, clear of the row over it, the typed text on the line the row's text takes, and
/// its ⋯ on the surface in the same ink; in light and dark.
#[test]
fn a_literal_draft_row_is_spaced_as_an_attribute_draft_row_and_clear_of_the_row_over_it() {
    for theme in [ThemeKind::Light, ThemeKind::Dark] {
        let (mut h, order, status) = nested_orders(theme);
        let p = crate::ux::palette(theme == ThemeKind::Dark);
        let mut rings = Vec::new();
        for (class, kind, over) in [
            (status, crate::uml_panel::MemberKind::Literal, "Shipped"),
            (order, crate::uml_panel::MemberKind::Attribute, "+ total : Money"),
            (order, crate::uml_panel::MemberKind::Operation, "+ pay() : Boolean"),
        ] {
            assert!(crate::uml_inline::open(h.state_mut(), class, kind, None), "{kind:?}'s draft opens");
            h.state_mut().canvas.inline.as_mut().unwrap().edit.name = "Returned".into();
            h.run();
            // Its ring: the accent's outline round the tinted row, a row's height, not a card's.
            let tinted: Vec<egui::Rect> = rect_shapes(&h).into_iter().filter(|(_, fill, _)| *fill == p.accent_tint).map(|(r, _, _)| r).collect();
            let ring = rect_shapes(&h).into_iter().find(|(r, _, stroke)| *stroke == p.accent && tinted.contains(r)).map(|(r, _, _)| r);
            let ring = ring.unwrap_or_else(|| panic!("{theme:?}: {kind:?}'s draft ringed"));
            let boxes = text_boxes(&h);
            let card = rect_of(&h, &format!("workspace.canvas.node.{}", node_of(&h, class)));
            let above = boxes.iter().find(|(t, r)| t == over && card.contains(r.center())).map(|(_, r)| *r).expect("the row over the draft");
            let typed = boxes.iter().find(|(t, r)| t == "Returned" && ring.contains(r.center())).map(|(_, r)| *r).expect("the typed name");
            assert!(ring.top() >= above.bottom(), "{theme:?}: {kind:?}'s ring at {} clear of {over} ending at {}", ring.top(), above.bottom());
            assert!((ring.height() - crate::canvas::ENTITY_ROW).abs() < 0.5, "{theme:?}: a row's pitch, not {}", ring.height());
            // The typed text sits on the line a row's text takes: a pitch under the row over it.
            let pitch = typed.center().y - above.center().y;
            assert!((pitch - crate::canvas::ENTITY_ROW).abs() < 1.0, "{theme:?}: {kind:?}'s draft a pitch under {over}, not {pitch}");
            // Its ⋯ on the surface at the ring's right.
            assert!(
                rect_shapes(&h).iter().any(|(r, fill, _)| *fill == p.surface && ring.contains_rect(*r) && r.right() > ring.right() - 24.0),
                "{theme:?}: {kind:?}'s ⋯ on the surface"
            );
            rings.push((ring.top() - above.bottom(), ring.height()));
            key(&mut h, egui::Key::Escape, egui::Modifiers::NONE);
            assert!(h.state().canvas.inline.is_none());
        }
        assert_eq!(rings[0], rings[1], "{theme:?}: a literal's draft is spaced as an attribute's");
        assert_eq!(rings[0], rings[2], "{theme:?}: a literal's draft is spaced as an operation's");
        assert_eq!(crate::uml_inline::details_ink(p), p.text_secondary, "one ⋯ ink for every member's row");
    }
}

/// A new class is placed at its default size, grows on every diagram as operations are added (one
/// undo step taking back the growth), keeps a size set by hand and then says the rows it hides in
/// its `+ n more` row, at any zoom; in light and dark.
#[test]
fn a_new_class_shows_the_operations_added_to_it_and_a_card_made_short_says_what_it_hides() {
    for theme in [ThemeKind::Light, ThemeKind::Dark] {
        let mut h = workspace_harness(theme, egui::vec2(1600.0, 1000.0));
        let run = |h: &mut Harness<'static, Shell>, command: &str, params: serde_json::Value| {
            let out = h.state_mut().session.as_mut().unwrap().execute(command, &params).unwrap_or_else(|e| panic!("{command}: {e}"));
            out.value["id"].as_str().map(|i| archforge_mof::Uuid::parse(i).unwrap())
        };
        let pkg = run(&mut h, "uml.package.add", serde_json::json!({ "name": "Billing" })).unwrap();
        let d = run(&mut h, "diagram.add", serde_json::json!({ "kind": "uml.class", "element": pkg.to_string(), "name": "Billing" })).unwrap();
        crate::canvas::open(h.state_mut(), d);
        let class = run(&mut h, "uml.class.add", serde_json::json!({ "package": pkg.to_string(), "name": "ReviewInvoice" })).unwrap();
        let node =
            run(&mut h, "diagram.place", serde_json::json!({ "diagram": d.to_string(), "element": class.to_string(), "x": 200, "y": 200 })).unwrap();
        let height = |h: &Harness<'static, Shell>| {
            let st = h.state().session.as_ref().unwrap().doc();
            archforge_diagram::grid::bounds_of(st, st.by_uuid(node).unwrap()).height
        };
        assert_eq!(height(&h), archforge_uml::CLASS_SIZE.1, "a new class is as tall as a row in each compartment");
        // The same class on two more diagrams: wider and short, and already tall.
        let mut others = Vec::new();
        for (name, width, tall) in [("Wide", 300, 150), ("Tall", 260, 400)] {
            let other = run(&mut h, "diagram.add", serde_json::json!({ "kind": "uml.class", "element": pkg.to_string(), "name": name })).unwrap();
            let n = run(
                &mut h,
                "diagram.place",
                serde_json::json!({ "diagram": other.to_string(), "element": class.to_string(), "x": 0, "y": 0, "width": width, "height": tall }),
            )
            .unwrap();
            others.push(n);
        }
        let size = |h: &Harness<'static, Shell>, n: archforge_mof::Uuid| {
            let st = h.state().session.as_ref().unwrap().doc();
            let b = archforge_diagram::grid::bounds_of(st, st.by_uuid(n).unwrap());
            (b.width, b.height)
        };
        h.state_mut().session.as_mut().unwrap().execute("view.select", &serde_json::json!({ "ids": [class.to_string()] })).unwrap();
        h.state_mut().state.show_panel(crate::state::Panel::Properties);
        h.run();
        // The first operation, added in Properties, shows on the card at its default size.
        let add_operation = |h: &mut Harness<'static, Shell>, name: &str| {
            let at = rect_of(h, "workspace.properties.operations.add").center();
            click(h, at);
            h.event(egui::Event::Text(name.into()));
            h.run();
            let at = rect_of(h, "workspace.properties.member.apply").center();
            click(h, at);
            assert!(h.state().panels.member.is_none(), "{:?}", h.state().panels.member);
            h.run();
        };
        add_operation(&mut h, "calculateTotal");
        assert_eq!(height(&h), archforge_uml::CLASS_SIZE.1, "nothing grows while every row fits");
        // Each member is painted twice: on the card and as its row in Properties.
        let on_card = |h: &Harness<'static, Shell>, row: &str| painted(h).iter().filter(|t| *t == row).count() == 2;
        assert!(on_card(&h, "+ calculateTotal()"), "{theme:?}: {:?}", painted(&h));
        assert!(!painted(&h).iter().any(|t| t.contains("more member")));
        // A second one grows the card to show both, in the same undo step; its width stays.
        add_operation(&mut h, "approve");
        let grown = height(&h);
        assert!(grown > archforge_uml::CLASS_SIZE.1, "{grown}");
        assert!(on_card(&h, "+ calculateTotal()") && on_card(&h, "+ approve()"), "{:?}", painted(&h));
        // Every card of the class grows on every diagram, keeping its width; a taller one is left.
        assert_eq!((size(&h, others[0]), size(&h, others[1])), ((300.0, grown), (260.0, 400.0)));
        h.state_mut().session.as_mut().unwrap().undo().unwrap();
        assert_eq!((member_rows(&h, class, true).len(), height(&h)), (1, archforge_uml::CLASS_SIZE.1), "one undo takes back both");
        assert_eq!((size(&h, others[0]), size(&h, others[1])), ((300.0, 150.0), (260.0, 400.0)), "and every card's height");
        h.state_mut().session.as_mut().unwrap().redo().unwrap();
        assert_eq!((member_rows(&h, class, true).len(), height(&h)), (2, grown));
        assert_eq!(size(&h, others[0]), (300.0, grown));
        // Made short by hand it stays so, and says what it hides rather than looking empty.
        run(&mut h, "diagram.resize", serde_json::json!({ "node": node.to_string(), "width": 240, "height": 120 }));
        h.run();
        let texts = painted(&h);
        assert!(texts.iter().any(|t| t == "+ 2 more members"), "{theme:?}: {texts:?}");
        assert!(!on_card(&h, "+ calculateTotal()") && !on_card(&h, "+ approve()"), "{texts:?}");
        assert_eq!(height(&h), 120.0);
        // Shorter than a row's place under the header, it says so at its foot, then beside its eyebrow.
        for short in [90, 60] {
            run(&mut h, "diagram.resize", serde_json::json!({ "node": node.to_string(), "width": 240, "height": short }));
            h.run();
            assert!(painted(&h).iter().any(|t| t == "+ 2 more members"), "{short} tall: {:?}", painted(&h));
        }
        run(&mut h, "diagram.resize", serde_json::json!({ "node": node.to_string(), "width": 240, "height": 120 }));
        h.run();
        // Seen at a reduced zoom, the card still says it.
        let zoom = h.state().canvas.zoom;
        h.state_mut().canvas.zoom = 0.6;
        h.run();
        assert!(painted(&h).iter().any(|t| t == "+ 2 more members"), "at 60 %");
        h.state_mut().canvas.zoom = zoom;
        // With an attribute it shows, the hint takes an operation's place and counts the rest.
        run(&mut h, "uml.attribute.add", serde_json::json!({ "class": class.to_string(), "name": "number" }));
        run(&mut h, "diagram.resize", serde_json::json!({ "node": node.to_string(), "width": 240, "height": archforge_uml::CLASS_SIZE.1 }));
        h.run();
        let texts = painted(&h);
        assert!(on_card(&h, "+ number"), "{texts:?}");
        assert!(texts.iter().any(|t| t == "+ 2 more members"), "{texts:?}");
        assert!(!on_card(&h, "+ calculateTotal()") && !on_card(&h, "+ approve()"), "{texts:?}");
        // Editing a member grows it again.
        let st = h.state().session.as_ref().unwrap().doc();
        let op = st.uuid(archforge_uml::members::operations(st, st.by_uuid(class).unwrap())[1]).unwrap();
        h.run();
        let at = rect_of(&h, &format!("workspace.properties.operation.{op}.edit")).center();
        click(&mut h, at);
        h.state_mut().panels.member.as_mut().unwrap().name = "approveAll".into();
        let at = rect_of(&h, "workspace.properties.member.apply").center();
        click(&mut h, at);
        h.run();
        assert_eq!(height(&h), grown);
        assert!(on_card(&h, "+ approveAll()"), "{:?}", painted(&h));
        // Saved and opened again from the project's rows, the card keeps its size.
        let (tables, junctions) = archforge_notations::storage();
        let rows = archforge_mof::rows::snapshot(h.state().session.as_ref().unwrap().doc(), &tables, &junctions).unwrap();
        let back = archforge_notations::session_from_rows(&rows, Box::new(|| archforge_mof::Uuid::v7(1_761_670_900_000, [9; 10]))).unwrap();
        let st = back.doc();
        assert_eq!(archforge_diagram::grid::bounds_of(st, st.by_uuid(node).unwrap()).height, grown);
        assert_eq!(archforge_uml::members::operations(st, st.by_uuid(class).unwrap()).len(), 2);
    }
}

#[test]
fn a_table_box_shorter_than_its_columns_shows_those_that_fit_and_counts_the_rest() {
    let (mut h, customer, diagram) = diagram_harness();
    let s = h.state_mut().session.as_mut().unwrap();
    for name in ["name", "phone", "city"] {
        s.execute("er.attribute.add", &serde_json::json!({ "entity": customer, "name": name, "type": "TEXT" })).unwrap();
    }
    h.run();
    let st = h.state().session.as_ref().unwrap().doc();
    let (e, d) =
        (st.by_uuid(archforge_mof::Uuid::parse(&customer).unwrap()).unwrap(), st.by_uuid(archforge_mof::Uuid::parse(&diagram).unwrap()).unwrap());
    let rows: Vec<String> =
        archforge_diagram::Notation::card(&archforge_er::ErNotation, st, e, d).unwrap().compartments[0].iter().map(|r| r.text.clone()).collect();
    assert_eq!(rows.len(), 5);
    // Its box, 166 tall, holds four rows' places: three columns, then the two past it said in one.
    // A column is painted in the Models tree and, when it shows, in its box too.
    let texts = painted(&h);
    let times = |row: &String| texts.iter().filter(|t| *t == row).count();
    assert_eq!(rows.iter().map(times).collect::<Vec<_>>(), [2, 2, 2, 1, 1], "{texts:?}");
    assert!(texts.iter().any(|t| t == "+ 2 more columns"), "{texts:?}");
}

/// The sample class model with the Chat panel shown, over the fake agents host and conversations
/// kept in memory (`crate::chat_fixture`), Claude set up and Let Chat use the model on when
/// `ready`.
fn chat_harness(theme: ThemeKind, ready: bool) -> (Harness<'static, Shell>, crate::chat_fixture::Rig) {
    crate::i18n::set_language("en");
    let mut shell = Shell::new(Services { ids: Some(test_ids()), ..Services::default() });
    shell.state.theme = theme;
    shell.open_project(crate::Opened { name: "Commerce platform".into(), path: "/tmp/Commerce platform.archforge".into(), ..Default::default() });
    let rig = crate::chat_fixture::sample(&mut shell, ready).unwrap();
    let h = harness_over(shell);
    (h, rig)
}

/// Types `text` into the composer and presses Enter, as the person does.
fn ask_in_chat(h: &mut Harness<'static, Shell>, text: &str) {
    let at = rect_of(h, "workspace.chat.composer").center();
    click(h, at);
    h.event(egui::Event::Text(text.into()));
    h.run();
    key(h, egui::Key::Enter, egui::Modifiers::NONE);
    // The composer's caret blinks while it has the keyboard: let it go, so the window settles.
    h.ctx.memory_mut(|m| m.surrender_focus(crate::widgets::egui_id("workspace.chat.composer")));
    h.run();
}

/// The host says `event` of the conversation shown.
fn chat_event(h: &mut Harness<'static, Shell>, rig: &crate::chat_fixture::Rig, event: crate::chat::ChatEvent) {
    let key = crate::chat_fixture::key(h.state());
    assert!(rig.agents.emit(&key, event), "the shell takes the conversation's events");
    h.run();
}

/// How many times `text` is painted whole.
fn painted_times(h: &Harness<'static, Shell>, text: &str) -> usize {
    painted(h).iter().filter(|t| t.as_str() == text).count()
}

/// The conversation shown, as the store keeps it.
fn kept_chat(h: &Harness<'static, Shell>, rig: &crate::chat_fixture::Rig) -> crate::chat_store::fake::Kept {
    let id = h.state().chat_panel.chat.as_ref().map(|c| c.id).unwrap();
    rig.store.kept(id).unwrap()
}

/// The fake host's conversation calls: starts, sends, stops, ends.
fn chat_calls(rig: &crate::chat_fixture::Rig) -> (usize, usize, usize, usize) {
    use std::sync::atomic::Ordering::Relaxed;
    let c = &rig.agents.calls;
    (c.start.load(Relaxed), c.send.load(Relaxed), c.stop.load(Relaxed), c.end.load(Relaxed))
}

/// A turn's end failed with `kind`.
fn failed_turn(kind: crate::chat::FailureKind) -> crate::chat::ChatEvent {
    crate::chat::ChatEvent::TurnEnded(crate::chat::TurnEnd::Failed(crate::chat::ChatFailure { kind, detail: "x".into(), reset: None }))
}

/// B1 without an agent (AR-63 rewritten): Configure agent opens Settings; B2 with one: intro, chips, composer, badge, switch.
#[test]
fn the_chat_icon_opens_configure_agent_without_an_agent_and_a_ready_conversation_with_one() {
    for theme in [ThemeKind::Light, ThemeKind::Dark] {
        // B1: no agent set up. Configure agent opens Settings on AI Agents; no composer.
        let (mut h, _rig) = chat_harness(theme, false);
        assert_eq!(h.state().state.panel, crate::state::Panel::Agent);
        assert!(painted_has(&h, "No agent set up yet") && painted_has(&h, "Configure agent"), "{theme:?}: {:?}", painted(&h));
        let found = ids(&h);
        assert!(found.iter().any(|i| i == "workspace.chat.history"), "{theme:?}");
        for absent in ["workspace.chat.new", "workspace.chat.composer", "workspace.chat.send", "workspace.chat.badge"] {
            assert!(!found.iter().any(|i| i == absent), "{theme:?}: {absent} in B1");
        }
        let at = rect_of(&h, "workspace.chat.configure").center();
        click(&mut h, at);
        assert_eq!(h.state().settings.as_ref().map(|d| d.section), Some(crate::settings::Section::Agents), "{theme:?}");

        // B2: ready. The intro, the three chips, the notice, the composer with Claude's badge and
        // Send, Allow changes off.
        let (mut h, _rig) = chat_harness(theme, true);
        for text in ["Ask about Commerce platform", "These and everything the agent reads are sent to the provider.", "Allow changes to the model"] {
            assert!(painted_has(&h, text), "{theme:?}: {text} in {:?}", painted(&h));
        }
        assert!(painted_has(&h, "Claude · Sonnet"), "{theme:?}: the badge names the model asked for");
        let found = ids(&h);
        for id in [
            "workspace.chat.history",
            "workspace.chat.new",
            "workspace.chat.composer",
            "workspace.chat.send",
            "workspace.chat.badge",
            "workspace.chat.allow-changes",
            "workspace.chat.chip.project.remove",
            "workspace.chat.chip.diagram.remove",
            "workspace.chat.chip.selection.remove",
        ] {
            assert!(found.iter().any(|i| i == id), "{theme:?}: {id} in {found:?}");
        }
        assert!(!h.state().chat_panel.chat.as_ref().unwrap().allow_changes, "a conversation starts read-only");
        // Nothing of Properties is drawn under it; back to Properties, the selection is as it was.
        assert!(!found.iter().any(|i| i.starts_with("workspace.properties.") || i.starts_with("workspace.skills.")), "{theme:?}");
        let at = rect_of(&h, "workspace.panels.properties").center();
        click(&mut h, at);
        assert!(painted(&h).iter().any(|t| t == "Order"));
        // Its icon again shows the same conversation; a second click on the open panel folds the dock.
        let chat = h.state().chat_panel.chat.as_ref().map(|c| c.id);
        let at = rect_of(&h, "workspace.panels.agent").center();
        click(&mut h, at);
        assert_eq!(h.state().chat_panel.chat.as_ref().map(|c| c.id), chat);
        click(&mut h, at);
        assert!(h.state().state.panel_collapsed);
    }
}

/// A question is kept before the agent gets it, with its chips as a context line; Enter sends, Shift+Enter starts a line.
#[test]
fn a_question_is_kept_before_it_is_sent_with_its_chips_as_a_context_line_and_streams_back() {
    use crate::chat::ChatEvent;
    let (mut h, rig) = chat_harness(ThemeKind::Light, true);
    // A removed chip stays removed for the conversation and is not sent.
    let at = rect_of(&h, "workspace.chat.chip.project.remove").center();
    click(&mut h, at);
    assert!(!ids(&h).iter().any(|i| i == "workspace.chat.chip.project.remove"));
    ask_in_chat(&mut h, "Which classes have no description yet?");
    assert_eq!(*rig.store.log.lock().unwrap(), ["create", "ask"], "made and asked before the agent gets it");
    assert_eq!(h.state().chat_panel.draft, "", "the composer empties once the question is kept");
    let started = rig.agents.started.lock().unwrap().clone();
    assert_eq!(started.len(), 1);
    let start = &started[0];
    assert_eq!(
        (start.provider, start.model.as_str(), start.origin.as_str(), start.allow_changes, start.resume),
        (crate::ai_agents::Provider::Claude, "sonnet", "Chat 1", false, false)
    );
    assert_eq!(chat_calls(&rig).1, 1, "sent once");
    let chat = kept_chat(&h, &rig);
    assert_eq!((chat.row.origin.as_str(), chat.row.title.as_str()), ("Chat 1", "Which classes have no description yet?"));
    // The chips go as a line after the question, by name and id; the removed one does not.
    let order = crate::chat_fixture::element(h.state(), archforge_uml::CLASS, "Order").unwrap();
    let line = crate::chat_panel::context_line(
        &crate::chat_panel::chips(h.state())
            .into_iter()
            .filter(|c| c.chip != crate::chat_panel::Chip::Project)
            .flat_map(|c| c.anchors)
            .collect::<Vec<_>>(),
    );
    assert!(line.contains("selected \"Order\"") && line.contains(&order.to_string()) && line.contains("open diagram \"Commerce\""), "{line}");
    assert!(!line.contains("project"), "{line}");
    // The reply streams, then completes; Started names the model on the badge.
    chat_event(&mut h, &rig, ChatEvent::Started { model: crate::chat_fixture::NAMED.into(), access: true });
    assert!(painted_has(&h, "Claude · Sonnet 4.5"));
    chat_event(&mut h, &rig, ChatEvent::Text { delta: "Five of the eight ".into() });
    assert!(painted_has(&h, "Five of the eight ▍") || painted_has(&h, "Five of the eight"), "{:?}", painted(&h));
    assert!(ids(&h).iter().any(|i| i == "workspace.chat.stop") && !ids(&h).iter().any(|i| i == "workspace.chat.send"));
    assert!(painted_has(&h, "Claude is replying… you can type the next message"));
    chat_event(&mut h, &rig, ChatEvent::Message { text: "Five of the **eight** classes.".into() });
    chat_event(&mut h, &rig, ChatEvent::TurnEnded(crate::chat::TurnEnd::Completed));
    assert!(painted_has(&h, "Five of the eight classes."), "rendered as Markdown: {:?}", painted(&h));
    let chat = kept_chat(&h, &rig);
    assert_eq!(chat.turns[0].outcome, crate::chat_store::Outcome::Completed);
    assert!(
        matches!(&chat.messages[1].body, crate::chat_store::StoredBody::Reply { text, complete: true, .. } if text == "Five of the **eight** classes.")
    );
    // Enter sends, Shift+Enter makes a new line.
    let at = rect_of(&h, "workspace.chat.composer").center();
    click(&mut h, at);
    h.event(egui::Event::Text("Line one".into()));
    key(&mut h, egui::Key::Enter, egui::Modifiers::SHIFT);
    h.event(egui::Event::Text("line two".into()));
    h.run();
    assert_eq!(h.state().chat_panel.draft, "Line one\nline two");
    assert_eq!(chat_calls(&rig).1, 1, "Shift+Enter sent nothing");
}

/// The "Sign-in expired" card of a Codex conversation reads Codex's sign-in again (AR-222), so
/// Settings shows it expired, with its email, without a restart. In both appearances.
#[test]
fn a_codex_sign_in_expired_card_reads_the_sign_in_again() {
    use crate::ai_agents::{CodexAccount, Provider};
    use crate::chat::{ChatEvent, ChatFailure, FailureKind, TurnEnd};
    use std::sync::atomic::Ordering::Relaxed;
    for theme in [ThemeKind::Light, ThemeKind::Dark] {
        let (mut h, rig) = chat_harness(theme, true);
        *rig.agents.account.lock().unwrap() = Ok(CodexAccount::SignedIn { email: "you@example.com".into(), plan: None });
        h.state_mut().state.agents.default_agent = Provider::Codex;
        h.run();
        ask_in_chat(&mut h, "Hello");
        assert_eq!(rig.agents.started.lock().unwrap().last().map(|s| s.provider), Some(Provider::Codex));
        let reads = rig.agents.calls.account.load(Relaxed);
        assert_eq!(h.state().agents.codex, Some(Ok(CodexAccount::SignedIn { email: "you@example.com".into(), plan: None })));
        *rig.agents.account.lock().unwrap() = Ok(CodexAccount::Expired { email: String::new() });
        let expired = ChatFailure { kind: FailureKind::SignInExpired, detail: "x".into(), reset: None };
        chat_event(&mut h, &rig, ChatEvent::TurnEnded(TurnEnd::Failed(expired)));
        assert!(painted_has(&h, "Sign-in expired"));
        assert_eq!(rig.agents.calls.account.load(Relaxed), reads + 1, "{theme:?}: the card read the sign-in again");
        h.run();
        assert_eq!(h.state().agents.codex, Some(Ok(CodexAccount::Expired { email: "you@example.com".into() })), "expired, its email kept");
        // Should the codex program still read it as signed in (it may not try to refresh it), the
        // card's word stands until a sign-in or a sign-out.
        *rig.agents.account.lock().unwrap() = Ok(CodexAccount::SignedIn { email: "you@example.com".into(), plan: None });
        crate::ai_agents::reread_account(h.state_mut());
        h.run();
        assert_eq!(rig.agents.calls.account.load(Relaxed), reads + 2);
        assert_eq!(h.state().agents.codex, Some(Ok(CodexAccount::Expired { email: "you@example.com".into() })), "still expired");
    }
}

/// A parked tab's Codex conversation whose turn ends with an expired sign-in reads Codex's sign-in
/// again and shows it expired, with its email, as the conversation shown does (AR-222). In both
/// appearances.
#[test]
fn a_parked_codex_conversations_sign_in_expired_card_reads_the_sign_in_again() {
    use crate::ai_agents::{CodexAccount, Provider};
    use crate::chat::{ChatEvent, ChatFailure, FailureKind, TurnEnd};
    use std::sync::atomic::Ordering::Relaxed;
    for theme in [ThemeKind::Light, ThemeKind::Dark] {
        let (mut h, rig) = chat_harness(theme, true);
        *rig.agents.account.lock().unwrap() = Ok(CodexAccount::SignedIn { email: "you@example.com".into(), plan: None });
        h.state_mut().state.agents.default_agent = Provider::Codex;
        h.run();
        ask_in_chat(&mut h, "Hello");
        let key = crate::chat_fixture::key(h.state());
        let first = h.state().active.unwrap();
        h.state_mut().open_project(crate::Opened { name: "Second".into(), path: "/tmp/Second.archforge".into(), ..Default::default() });
        h.run();
        assert!(h.state().tabs[first].parked.as_ref().is_some_and(|p| p.chat_panel.chat.is_some()), "{theme:?}: parked");
        let reads = rig.agents.calls.account.load(Relaxed);
        *rig.agents.account.lock().unwrap() = Ok(CodexAccount::Expired { email: String::new() });
        let expired = ChatFailure { kind: FailureKind::SignInExpired, detail: "x".into(), reset: None };
        assert!(rig.agents.emit(&key, ChatEvent::TurnEnded(TurnEnd::Failed(expired))));
        h.run();
        h.run();
        assert_eq!(rig.agents.calls.account.load(Relaxed), reads + 1, "{theme:?}: the parked card read the sign-in again");
        assert_eq!(h.state().agents.codex, Some(Ok(CodexAccount::Expired { email: "you@example.com".into() })), "{theme:?}");
    }
}

/// Turning Let Chat use the model off ends a conversation that runs (AR-221): its program ends, the
/// reply so far stays, marked stopped, the panel says why, and the next question is neither sent
/// nor kept; it stays in the box. Turned on again, the question goes.
#[test]
fn turning_model_use_off_ends_a_running_conversation_and_sends_nothing_more() {
    use crate::chat::ChatEvent;
    const OFF: &str = "Let Chat use the model is off, so nothing is sent. Turn it on in Settings ▸ AI Agents.";
    let (mut h, rig) = chat_harness(ThemeKind::Light, true);
    ask_in_chat(&mut h, "Explain how Payment relates to Order.");
    chat_event(&mut h, &rig, ChatEvent::Text { delta: "Payment is linked to Order by".into() });
    assert_eq!(chat_calls(&rig), (1, 1, 0, 0));
    h.state_mut().state.agents.chat_uses_model = false;
    h.run();
    assert_eq!(chat_calls(&rig).3, 1, "the running conversation's program ends");
    assert!(painted_has(&h, "Payment is linked to Order by"), "the reply so far stays");
    assert_eq!(kept_chat(&h, &rig).turns[0].outcome, crate::chat_store::Outcome::Stopped);
    assert!(painted_has(&h, OFF), "{:?}", painted(&h));
    let log = rig.store.log.lock().unwrap().len();
    ask_in_chat(&mut h, "And how does Invoice relate to Order?");
    assert_eq!((chat_calls(&rig).0, chat_calls(&rig).1), (1, 1), "nothing more is started or sent");
    assert_eq!(rig.store.log.lock().unwrap().len(), log, "nor kept");
    assert_eq!(h.state().chat_panel.draft, "And how does Invoice relate to Order?", "the question stays in the box");
    assert!(painted_has(&h, OFF));
    // On again: the line goes, and the question in the box is sent.
    h.state_mut().state.agents.chat_uses_model = true;
    h.run();
    assert!(!painted_has(&h, OFF));
    let at = rect_of(&h, "workspace.chat.composer").center();
    click(&mut h, at);
    key(&mut h, egui::Key::Enter, egui::Modifiers::NONE);
    h.ctx.memory_mut(|m| m.surrender_focus(crate::widgets::egui_id("workspace.chat.composer")));
    h.run();
    assert_eq!((chat_calls(&rig).0, chat_calls(&rig).1), (2, 2), "started again and sent");
}

/// Off and on again before the ended program has gone (AR-221): a question asked meanwhile waits
/// for its end, then starts the program again and is sent, never lost into the ending one.
#[test]
fn a_question_asked_after_model_use_is_off_and_on_again_waits_for_the_end_then_goes() {
    use crate::chat::ChatEvent;
    let (mut h, rig) = chat_harness(ThemeKind::Light, true);
    ask_in_chat(&mut h, "Explain how Payment relates to Order.");
    chat_event(&mut h, &rig, ChatEvent::Message { text: "Payment is linked to Order.".into() });
    chat_event(&mut h, &rig, ChatEvent::TurnEnded(crate::chat::TurnEnd::Completed));
    let key = crate::chat_fixture::key(h.state());
    rig.agents.hold_ends.store(true, std::sync::atomic::Ordering::Relaxed);
    h.state_mut().state.agents.chat_uses_model = false;
    h.run();
    assert_eq!(chat_calls(&rig).3, 1, "its program is asked to end");
    assert_eq!(h.state().chat_panel.chat.as_ref().map(|c| c.session), Some(crate::chat_panel::Session::Ending));
    h.state_mut().state.agents.chat_uses_model = true;
    h.run();
    ask_in_chat(&mut h, "And Invoice?");
    assert_eq!((chat_calls(&rig).0, chat_calls(&rig).1), (1, 1), "the question waits for the end");
    rig.agents.hold_ends.store(false, std::sync::atomic::Ordering::Relaxed);
    rig.agents.running.lock().unwrap().retain(|k| *k != key);
    chat_event(&mut h, &rig, ChatEvent::Ended { failure: None });
    assert_eq!((chat_calls(&rig).0, chat_calls(&rig).1), (2, 2), "then starts the program again and sends it");
    assert!(sent_texts(&rig).last().is_some_and(|t| t.starts_with("And Invoice?")));
}

/// Off while a question is still being kept (AR-221): it is not sent, its turn ends stopped, and
/// the question goes back into the empty box.
#[test]
fn a_question_being_kept_when_model_use_goes_off_is_not_sent_and_goes_back_to_the_box() {
    let (mut h, rig) = chat_harness(ThemeKind::Light, true);
    rig.store.hold.store(true, std::sync::atomic::Ordering::SeqCst);
    ask_in_chat(&mut h, "Explain how Payment relates to Order.");
    assert_eq!(chat_calls(&rig).0, 0, "still being kept");
    h.state_mut().state.agents.chat_uses_model = false;
    h.run();
    rig.store.release();
    for _ in 0..4 {
        h.run();
    }
    assert_eq!((chat_calls(&rig).0, chat_calls(&rig).1), (0, 0), "nothing started or sent");
    assert_eq!(h.state().chat_panel.draft, "Explain how Payment relates to Order.", "back in the box");
    assert_eq!(kept_chat(&h, &rig).turns[0].outcome, crate::chat_store::Outcome::Failed);
    assert!(painted_has(&h, "Not sent"));
    assert!(painted_has(&h, "Let Chat use the model is off, so nothing is sent. Turn it on in Settings ▸ AI Agents."));
    // On again, the box sends it in place: the same turn, now sent.
    h.state_mut().state.agents.chat_uses_model = true;
    h.run();
    let at = rect_of(&h, "workspace.chat.composer").center();
    click(&mut h, at);
    key(&mut h, egui::Key::Enter, egui::Modifiers::NONE);
    h.ctx.memory_mut(|m| m.surrender_focus(crate::widgets::egui_id("workspace.chat.composer")));
    h.run();
    assert_eq!((chat_calls(&rig).0, chat_calls(&rig).1), (1, 1));
    assert_eq!(h.state().chat_panel.chat.as_ref().map(|c| c.turns.len()), Some(1), "sent in place");
}

/// Off while a question is being kept and the box already holds something else (AR-221, review):
/// what was typed stays, the question stays in its bubble, and its card offers Send again, which
/// sends it once the switch is on again; nothing has to be typed twice.
#[test]
fn a_question_not_sent_while_the_box_holds_other_text_can_be_sent_again() {
    let (mut h, rig) = chat_harness(ThemeKind::Light, true);
    rig.store.hold.store(true, std::sync::atomic::Ordering::SeqCst);
    ask_in_chat(&mut h, "Explain how Payment relates to Order.");
    // The person writes something else in the box meanwhile.
    h.state_mut().chat_panel.draft = "A second thought".into();
    h.run();
    h.state_mut().state.agents.chat_uses_model = false;
    h.run();
    rig.store.release();
    for _ in 0..4 {
        h.run();
    }
    assert_eq!((chat_calls(&rig).0, chat_calls(&rig).1), (0, 0), "nothing started or sent");
    assert_eq!(h.state().chat_panel.draft, "A second thought", "what was typed stays");
    assert!(painted_has(&h, "Explain how Payment relates to Order."), "the question stays in its bubble");
    assert!(painted_has(&h, "Let Chat use the model was turned off, so this question was not sent. Send it again once the switch is on."));
    // Send again while it is still off sends nothing and says why.
    let at = rect_of(&h, "workspace.chat.turn.1.retry").center();
    click(&mut h, at);
    assert_eq!((chat_calls(&rig).0, chat_calls(&rig).1), (0, 0));
    // On again, Send again sends the question as it was, in place, and the box keeps its text.
    h.state_mut().state.agents.chat_uses_model = true;
    h.run();
    let at = rect_of(&h, "workspace.chat.turn.1.retry").center();
    click(&mut h, at);
    h.run();
    assert_eq!((chat_calls(&rig).0, chat_calls(&rig).1), (1, 1));
    assert!(sent_texts(&rig).last().is_some_and(|t| t.starts_with("Explain how Payment relates to Order.")));
    assert_eq!(h.state().chat_panel.draft, "A second thought");
    assert_eq!(h.state().chat_panel.chat.as_ref().map(|c| c.turns.len()), Some(1), "sent in place");
}

/// A conversation opened again from the history while Let Chat use the model is off sends nothing
/// (AR-221): neither its question nor, by resuming, what it said before; the panel says why.
#[test]
fn a_conversation_reopened_while_model_use_is_off_sends_nothing() {
    use crate::chat::ChatEvent;
    let (mut h, rig) = chat_harness(ThemeKind::Light, true);
    ask_in_chat(&mut h, "Explain how Payment relates to Order.");
    chat_event(&mut h, &rig, ChatEvent::Message { text: "Payment is linked to Order.".into() });
    chat_event(&mut h, &rig, ChatEvent::TurnEnded(crate::chat::TurnEnd::Completed));
    let at = rect_of(&h, "workspace.chat.new").center();
    click(&mut h, at);
    assert_eq!(chat_calls(&rig), (1, 1, 0, 1), "a new conversation ended the first one's program");
    h.state_mut().state.agents.chat_uses_model = false;
    h.run();
    let at = rect_of(&h, "workspace.chat.history").center();
    click(&mut h, at);
    let at = rect_of(&h, "workspace.chat.history.0").center();
    click(&mut h, at);
    h.run();
    assert_eq!(h.state().chat_panel.chat.as_ref().map(|c| c.turns.len()), Some(1), "open again with what it said");
    assert!(painted_has(&h, "Payment is linked to Order."));
    let log = rig.store.log.lock().unwrap().len();
    ask_in_chat(&mut h, "Go on from there.");
    assert_eq!((chat_calls(&rig).0, chat_calls(&rig).1), (1, 1), "nothing started or sent: neither the question nor, by resuming, the history");
    assert_eq!(rig.store.log.lock().unwrap().len(), log, "nor kept");
    assert_eq!(h.state().chat_panel.draft, "Go on from there.");
    assert!(painted_has(&h, "Let Chat use the model is off, so nothing is sent. Turn it on in Settings ▸ AI Agents."));
}

/// Stop keeps the reply so far, marked cut off and kept; an unreachable program's turn ends here.
#[test]
fn stop_keeps_the_reply_so_far_marked_cut_off_and_keeps_it_in_the_project() {
    use crate::chat::ChatEvent;
    for theme in [ThemeKind::Light, ThemeKind::Dark] {
        let (mut h, rig) = chat_harness(theme, true);
        ask_in_chat(&mut h, "Explain how Payment relates to Order.");
        chat_event(&mut h, &rig, ChatEvent::Text { delta: "Payment is linked to Order by".into() });
        let at = rect_of(&h, "workspace.chat.stop").center();
        click(&mut h, at);
        assert_eq!(chat_calls(&rig).2, 1, "{theme:?}: the program is asked to stop the turn");
        click(&mut h, at);
        assert_eq!(chat_calls(&rig).2, 1, "{theme:?}: once");
        chat_event(&mut h, &rig, ChatEvent::TurnEnded(crate::chat::TurnEnd::Stopped));
        assert!(painted_has(&h, "Payment is linked to Order by") && !painted_has(&h, "▍"), "{theme:?}: the reply so far stays");
        assert!(painted_has(&h, "Stopped. Nothing was changed."), "{theme:?}");
        let chat = kept_chat(&h, &rig);
        assert_eq!(chat.turns[0].outcome, crate::chat_store::Outcome::Stopped);
        assert!(
            matches!(&chat.messages[1].body, crate::chat_store::StoredBody::Reply { text, complete: false, .. } if text == "Payment is linked to Order by"),
            "{theme:?}: kept, marked cut off: {:?}",
            chat.messages
        );
        assert!(ids(&h).iter().any(|i| i == "workspace.chat.send"), "{theme:?}: Send is back");
        // A program that cannot be reached any more: the turn ends here as stopped.
        ask_in_chat(&mut h, "And Customer?");
        rig.agents.running.lock().unwrap().clear();
        let at = rect_of(&h, "workspace.chat.stop").center();
        click(&mut h, at);
        assert_eq!(kept_chat(&h, &rig).turns[1].outcome, crate::chat_store::Outcome::Stopped, "{theme:?}");
    }
}

/// Send again runs the failed turn in place: no new turn, the question shown and kept once.
#[test]
fn send_again_runs_the_failed_turn_in_place_and_its_question_shows_and_is_kept_once() {
    use crate::chat::{ChatEvent, FailureKind};
    use crate::chat_store::{Outcome, StoredBody};
    let question = "Which classes have no description yet?";
    let questions = |chat: &crate::chat_store::fake::Kept| -> Vec<String> {
        chat.messages.iter().filter_map(|m| if let StoredBody::Question { text, .. } = &m.body { Some(text.clone()) } else { None }).collect()
    };
    let (mut h, rig) = chat_harness(ThemeKind::Light, true);
    ask_in_chat(&mut h, question);
    chat_event(&mut h, &rig, failed_turn(FailureKind::Other));
    assert!(painted_has(&h, "No answer") && painted_has(&h, "Claude stopped before answering. Nothing was changed."), "{:?}", painted(&h));
    let at = rect_of(&h, "workspace.chat.turn.1.retry").center();
    click(&mut h, at);
    let chat = kept_chat(&h, &rig);
    assert_eq!((chat.turns.len(), chat.turns[0].outcome), (1, Outcome::Running), "the same turn runs again");
    assert_eq!(questions(&chat), [question], "the question is kept once");
    assert_eq!(painted_times(&h, question), 1, "and shown once");
    assert_eq!(chat_calls(&rig).1, 2, "the agent gets it again");
    assert!(rig.store.log.lock().unwrap().contains(&"rerun"));
    chat_event(&mut h, &rig, ChatEvent::Message { text: "Five of them.".into() });
    chat_event(&mut h, &rig, ChatEvent::TurnEnded(crate::chat::TurnEnd::Completed));
    assert_eq!(kept_chat(&h, &rig).turns.len(), 1);
    assert!(!ids(&h).iter().any(|i| i == "workspace.chat.turn.1.retry"), "a completed turn is not sent again");

    // A lost connection puts the question back in the empty composer, its bubble gone; edited and
    // sent, it replaces the kept one in place.
    let second = "List the classes without one.";
    ask_in_chat(&mut h, second);
    chat_event(&mut h, &rig, failed_turn(FailureKind::Network));
    assert_eq!(h.state().chat_panel.draft, second, "back in the composer");
    assert!(painted_has(&h, "Connection lost") && painted_has(&h, "Your message is back in the box below"), "{:?}", painted(&h));
    let at = rect_of(&h, "workspace.chat.composer").center();
    click(&mut h, at);
    key(&mut h, egui::Key::A, egui::Modifiers::COMMAND);
    h.event(egui::Event::Text("List every class without one.".into()));
    h.run();
    key(&mut h, egui::Key::Enter, egui::Modifiers::NONE);
    let chat = kept_chat(&h, &rig);
    assert_eq!(chat.turns.len(), 2, "no new turn");
    assert_eq!(questions(&chat), [question, "List every class without one."], "the edited question replaced the kept one");
    assert_eq!((painted_times(&h, second), painted_times(&h, "List every class without one.")), (0, 1));
    assert_eq!(h.state().chat_panel.draft, "");
}

/// The draft survives a project's refusal, a kept key in the question and a lost connection.
#[test]
fn the_draft_survives_a_lost_connection_and_a_project_that_refuses_the_question() {
    use crate::chat::FailureKind;
    for theme in [ThemeKind::Light, ThemeKind::Dark] {
        let (mut h, rig) = chat_harness(theme, true);
        // The project refuses: nothing is sent, the draft stays and the panel says why.
        *rig.store.refuse.lock().unwrap() = Some("the disk is full".into());
        ask_in_chat(&mut h, "Which classes have no description yet?");
        assert_eq!(h.state().chat_panel.draft, "Which classes have no description yet?", "{theme:?}");
        assert!(painted_has(&h, "This conversation could not be saved: the disk is full"), "{theme:?}: {:?}", painted(&h));
        assert_eq!(chat_calls(&rig), (0, 0, 0, 0), "{theme:?}: nothing reached the agent");
        // A question holding a kept key is refused before anything is written.
        *rig.store.refuse.lock().unwrap() = None;
        h.state_mut().chat_panel.draft.clear();
        ask_in_chat(&mut h, &format!("Why does {} fail?", crate::chat_fixture::KEY));
        assert!(painted_has(&h, "This question holds your saved Claude API key, so it was neither sent nor saved."), "{theme:?}");
        assert!(h.state().chat_panel.draft.contains(crate::chat_fixture::KEY), "{theme:?}: kept for the person to edit");
        assert!(rig.store.chats.lock().unwrap().iter().all(|c| !c.row.title.contains(crate::chat_fixture::KEY)));
        assert_eq!(chat_calls(&rig), (0, 0, 0, 0), "{theme:?}");
        // Sent once it can be: the draft empties. A lost connection with a new draft typed meanwhile
        // keeps that draft; the question stays in its bubble.
        h.state_mut().chat_panel.draft.clear();
        ask_in_chat(&mut h, "Which classes have no description yet?");
        assert_eq!(h.state().chat_panel.draft, "");
        let at = rect_of(&h, "workspace.chat.composer").center();
        click(&mut h, at);
        h.event(egui::Event::Text("And the next one".into()));
        h.run();
        // While the reply runs, typing works and Enter waits.
        key(&mut h, egui::Key::Enter, egui::Modifiers::NONE);
        assert_eq!(chat_calls(&rig).1, 1, "{theme:?}: Enter waits for the reply");
        assert!(painted_has(&h, "Stop the reply first"), "{theme:?}");
        chat_event(&mut h, &rig, failed_turn(FailureKind::Network));
        assert_eq!(h.state().chat_panel.draft, "And the next one", "{theme:?}: the draft typed meanwhile is kept");
        assert_eq!(painted_times(&h, "Which classes have no description yet?"), 1, "{theme:?}: the question stays in its bubble");
        assert!(painted_has(&h, "The network went away before Claude answered."), "{theme:?}");
    }
}

/// The badge names the model; Settings never switch a started conversation; the badge does, between turns.
#[test]
fn the_badge_names_the_model_and_a_changed_setting_never_switches_a_running_conversation() {
    use crate::ai_agents::Provider;
    use crate::chat::ChatEvent;
    let (mut h, rig) = chat_harness(ThemeKind::Light, true);
    // A conversation that has not started follows Settings.
    h.state_mut().state.agents.claude_model = "opus".into();
    h.run();
    assert!(painted_has(&h, "Claude · Opus"));
    h.state_mut().state.agents.claude_model = "sonnet".into();
    h.run();
    ask_in_chat(&mut h, "Hello");
    chat_event(&mut h, &rig, ChatEvent::Started { model: crate::chat_fixture::NAMED.into(), access: true });
    chat_event(&mut h, &rig, ChatEvent::TurnEnded(crate::chat::TurnEnd::Completed));
    // Settings change: the conversation keeps its agent and model, and its program.
    h.state_mut().state.agents.default_agent = Provider::Codex;
    h.state_mut().state.agents.claude_model = "opus".into();
    h.run();
    assert!(painted_has(&h, "Claude · Sonnet 4.5"), "{:?}", painted(&h));
    ask_in_chat(&mut h, "And again");
    assert_eq!(chat_calls(&rig), (1, 2, 0, 0), "the same program, no new start");
    chat_event(&mut h, &rig, ChatEvent::TurnEnded(crate::chat::TurnEnd::Completed));
    // While a reply runs, the badge, the switch, New conversation and the history wait.
    ask_in_chat(&mut h, "Third");
    for id in ["workspace.chat.badge", "workspace.chat.allow-changes", "workspace.chat.new", "workspace.chat.history"] {
        let at = rect_of(&h, id).center();
        click(&mut h, at);
    }
    let shown = h.state().chat_panel.chat.as_ref().unwrap();
    assert!(!h.state().chat_panel.menu && !shown.allow_changes && shown.turns.len() == 3, "nothing changed while it ran");
    assert_eq!(h.state().chat_panel.view, crate::chat_panel::View::Conversation);
    chat_event(&mut h, &rig, ChatEvent::TurnEnded(crate::chat::TurnEnd::Completed));
    // The badge's menu: once started, the conversation's own agent only; Opus picked ends the idle
    // program, and the next question starts it again where it was, on Opus.
    let at = rect_of(&h, "workspace.chat.badge").center();
    click(&mut h, at);
    assert!(h.state().chat_panel.menu);
    let items: Vec<String> = ids(&h).into_iter().filter(|i| i.starts_with("workspace.chat.badge.")).collect();
    assert_eq!(items.len(), Provider::Claude.models().len(), "{items:?}");
    let opus = Provider::Claude.models().iter().position(|(m, _)| *m == "opus").unwrap();
    let at = rect_of(&h, &format!("workspace.chat.badge.{opus}")).center();
    click(&mut h, at);
    assert_eq!(chat_calls(&rig).3, 1, "the idle program ended");
    assert!(painted_has(&h, "Claude · Opus"));
    assert!(rig.store.log.lock().unwrap().contains(&"model"));
    assert_eq!(h.state().chat_panel.chat.as_ref().unwrap().session, crate::chat_panel::Session::Off, "its end came");
    ask_in_chat(&mut h, "Fourth");
    let started = rig.agents.started.lock().unwrap().clone();
    assert_eq!(started.len(), 2);
    assert_eq!((started[1].provider, started[1].model.as_str(), started[1].resume), (Provider::Claude, "opus", true));
}

/// Only a web link in a reply is a control, and it opens only after its confirmation.
#[test]
fn only_a_web_link_in_a_reply_opens_and_only_after_its_confirmation() {
    use crate::chat::ChatEvent;
    let (mut h, rig) = chat_harness(ThemeKind::Light, true);
    ask_in_chat(&mut h, "Where are the docs?");
    let reply =
        "See [the docs](https://example.org/docs), [this](javascript:alert(1)), [mail](mailto:a@example.org) and [that](https://user@example.org/).";
    chat_event(&mut h, &rig, ChatEvent::Message { text: reply.into() });
    chat_event(&mut h, &rig, ChatEvent::TurnEnded(crate::chat::TurnEnd::Completed));
    let links: Vec<String> = ids(&h).into_iter().filter(|i| i.starts_with("workspace.chat.link.")).collect();
    assert_eq!(links, ["workspace.chat.link.0"], "only the web address is a link");
    let press = |h: &mut Harness<'static, Shell>, id: &str| {
        let at = rect_of(h, id).center();
        h.event(egui::Event::PointerMoved(at));
        h.run_steps(8);
        for pressed in [true, false] {
            h.event(egui::Event::PointerButton { pos: at, button: egui::PointerButton::Primary, pressed, modifiers: egui::Modifiers::NONE });
        }
        h.step();
    };
    press(&mut h, "workspace.chat.link.0");
    assert!(!h.output().platform_output.commands.iter().any(|c| matches!(c, egui::OutputCommand::OpenUrl(_))), "nothing opens yet");
    h.run_steps(8);
    assert_eq!(h.state().chat_panel.link.as_deref(), Some("https://example.org/docs"));
    press(&mut h, "workspace.chat.link.open");
    let opened: Vec<String> = h
        .output()
        .platform_output
        .commands
        .iter()
        .filter_map(|c| if let egui::OutputCommand::OpenUrl(u) = c { Some(u.url.clone()) } else { None })
        .collect();
    assert_eq!(opened, ["https://example.org/docs"]);
    h.run_steps(8);
    assert_eq!(h.state().chat_panel.link, None);
}

/// Undo this turn's changes takes back exactly the turn's changes, keeps the person's, and says when it cannot.
#[test]
fn undo_this_turns_changes_takes_back_exactly_the_turns_changes_and_keeps_the_persons() {
    use crate::chat::ChatEvent;
    use crate::chat_fixture as fx;
    let describe = |h: &mut Harness<'static, Shell>, name: &str, text: &str| {
        let id = fx::element(h.state(), archforge_uml::CLASS, name).unwrap();
        let answer = fx::call(
            h.state_mut(),
            "engine.execute",
            serde_json::json!({ "command": "element.describe", "params": { "element": id.to_string(), "text": text } }),
        );
        h.run();
        answer
    };
    let description = |h: &Harness<'static, Shell>, name: &str| {
        let s = h.state();
        let st = s.session.as_ref().unwrap().doc();
        let id = fx::element(s, archforge_uml::CLASS, name).unwrap();
        crate::panels::description_now(s, st.by_uuid(id).unwrap())
    };
    for theme in [ThemeKind::Light, ThemeKind::Dark] {
        let (mut h, rig) = chat_harness(theme, true);
        // The person's own edit first.
        let order = fx::element(h.state(), archforge_uml::CLASS, "Order").unwrap();
        h.state_mut()
            .session
            .as_mut()
            .unwrap()
            .execute("element.describe", &serde_json::json!({ "element": order.to_string(), "text": "Mine" }))
            .unwrap();
        // Read-only, a change is refused and its row says so.
        ask_in_chat(&mut h, "Describe Customer.");
        assert!(describe(&mut h, "Customer", "A buyer").is_err());
        assert!(painted_has(&h, "Changed Customer") && painted_has(&h, "refused"), "{theme:?}: {:?}", painted(&h));
        chat_event(&mut h, &rig, ChatEvent::TurnEnded(crate::chat::TurnEnd::Completed));
        // Changes allowed: two changes, one step of the undo history.
        let at = rect_of(&h, "workspace.chat.allow-changes").center();
        click(&mut h, at);
        assert!(h.state().chat_panel.chat.as_ref().unwrap().allow_changes);
        ask_in_chat(&mut h, "Describe Customer and Product.");
        describe(&mut h, "Customer", "A buyer").unwrap();
        describe(&mut h, "Product", "A thing sold").unwrap();
        chat_event(&mut h, &rig, ChatEvent::Message { text: "Done.".into() });
        chat_event(&mut h, &rig, ChatEvent::TurnEnded(crate::chat::TurnEnd::Completed));
        assert!(
            painted_has(&h, "2 changes to the model") && painted_has(&h, "Made in this turn, as one step of the project's undo history."),
            "{theme:?}"
        );
        assert_eq!(h.state().session.as_ref().unwrap().undo_label(), Some("Chat 1: Turn 2"));
        let kept = kept_chat(&h, &rig);
        let change = kept.turns[1].change.clone().unwrap();
        assert_eq!((change.changes, change.state), (2, crate::chat_store::ChangeState::Applied));
        let at = rect_of(&h, "workspace.chat.turn.2.undo").center();
        click(&mut h, at);
        assert_eq!(
            (description(&h, "Customer"), description(&h, "Product")),
            (String::new(), String::new()),
            "{theme:?}: the turn's changes are gone"
        );
        assert_eq!(description(&h, "Order"), "Mine", "{theme:?}: the person's own edit stays");
        assert!(painted_has(&h, "2 changes undone"), "{theme:?}");
        assert_eq!(kept_chat(&h, &rig).turns[1].change.as_ref().map(|c| c.state), Some(crate::chat_store::ChangeState::Undone));
        // Redo brings them back, and the record follows.
        h.state_mut().session.as_mut().unwrap().redo().unwrap();
        h.run();
        assert_eq!(description(&h, "Customer"), "A buyer");
        assert_eq!(kept_chat(&h, &rig).turns[1].change.as_ref().map(|c| c.state), Some(crate::chat_store::ChangeState::Applied));
        // Another change since: the turn's changes can no longer be undone on their own.
        h.state_mut()
            .session
            .as_mut()
            .unwrap()
            .execute("element.describe", &serde_json::json!({ "element": order.to_string(), "text": "Mine again" }))
            .unwrap();
        h.run();
        assert!(!ids(&h).iter().any(|i| i == "workspace.chat.turn.2.undo"), "{theme:?}");
        assert!(painted_has(&h, "The model changed after this turn, so its changes can no longer be undone on their own."), "{theme:?}");
    }
}

/// The history lists the project's conversations and opens one whole, read-only, resuming its program.
#[test]
fn the_history_lists_the_projects_conversations_and_opens_one_whole_and_read_only() {
    use crate::chat::ChatEvent;
    let (mut h, rig) = chat_harness(ThemeKind::Light, true);
    let at = rect_of(&h, "workspace.chat.allow-changes").center();
    click(&mut h, at);
    ask_in_chat(&mut h, "First question");
    chat_event(&mut h, &rig, ChatEvent::Message { text: "First answer".into() });
    chat_event(&mut h, &rig, ChatEvent::TurnEnded(crate::chat::TurnEnd::Completed));
    let first = h.state().chat_panel.chat.as_ref().unwrap().id;
    let at = rect_of(&h, "workspace.chat.new").center();
    click(&mut h, at);
    assert!(painted_has(&h, "Ask about Commerce platform"), "a new conversation");
    ask_in_chat(&mut h, "Second question");
    chat_event(&mut h, &rig, ChatEvent::TurnEnded(crate::chat::TurnEnd::Completed));
    let at = rect_of(&h, "workspace.chat.history").center();
    click(&mut h, at);
    assert!(painted_has(&h, "SAVED WITH COMMERCE PLATFORM"), "{:?}", painted(&h));
    assert!(painted_has(&h, "Conversations are kept in the project, so they travel with it and never show in another project."));
    let rows: Vec<String> = ids(&h).into_iter().filter(|i| i.starts_with("workspace.chat.history.")).collect();
    assert_eq!(rows.len(), 2);
    assert!(painted_has(&h, "Today 14:26 · Claude · 2 messages") && painted_has(&h, "Today 14:26 · Claude · 1 message"), "{:?}", painted(&h));
    // The older one, opened again: whole, read-only, its program not started until asked.
    let at = rect_of(&h, "workspace.chat.history.1").center();
    click(&mut h, at);
    let shown = h.state().chat_panel.chat.as_ref().unwrap();
    assert_eq!((shown.id, shown.turns.len(), shown.allow_changes), (first, 1, false));
    assert!(painted_has(&h, "First question") && painted_has(&h, "First answer"), "{:?}", painted(&h));
    let starts = chat_calls(&rig).0;
    ask_in_chat(&mut h, "Go on");
    let started = rig.agents.started.lock().unwrap().clone();
    assert_eq!(started.len(), starts + 1);
    let last = started.last().unwrap();
    assert_eq!((last.origin.as_str(), last.resume, last.allow_changes), ("Chat 1", true, false));
    assert_eq!(kept_chat(&h, &rig).turns.len(), 2, "its turns go on from where they were");
}

/// The Chat panel's history of page 07 (B7): five conversations kept, the first open, the history
/// shown; their ids in the list's order.
fn chat_history(theme: ThemeKind) -> (Harness<'static, Shell>, crate::chat_fixture::Rig, Vec<archforge_mof::Uuid>) {
    let (mut h, rig) = chat_harness(theme, true);
    let chats = crate::chat_fixture::history(h.state_mut(), &rig).unwrap();
    h.run();
    (h, rig, chats)
}

/// The pointer moved to `at`, nothing pressed.
fn point_at(h: &mut Harness<'static, Shell>, at: egui::Pos2) {
    h.event(egui::Event::PointerMoved(at));
    h.run();
}

/// The widget the keyboard is on, by automation id.
fn focused(h: &Harness<'static, Shell>) -> Option<String> {
    let id = h.ctx.memory(|m| m.focused())?;
    h.state().widgets().iter().find(|w| crate::widgets::egui_id(&w.id) == id).map(|w| w.id.clone())
}

/// The keyboard put on the control `id`, as Tab would bring it there.
fn focus_on(h: &mut Harness<'static, Shell>, id: &str) {
    h.ctx.memory_mut(|m| m.request_focus(crate::widgets::egui_id(id)));
    h.run();
}

/// Moves the fixed clock on by `secs` and draws a frame.
fn later(h: &mut Harness<'static, Shell>, rig: &crate::chat_fixture::Rig, secs: u64) {
    rig.now.fetch_add(secs, std::sync::atomic::Ordering::Relaxed);
    h.run();
}

/// The folders the fake host removed.
fn forgotten(rig: &crate::chat_fixture::Rig) -> Vec<String> {
    rig.agents.forgotten.lock().unwrap().clone()
}

/// B7a to B7c through the bin (AR-217): the bin shows on the row the pointer is on, the
/// confirmation names the conversation and what deleting does, starts on Cancel and Escape gives
/// the row its focus back; Delete takes the row away, writes one deletion, leaves the model and its
/// undo history alone, and the toast offers Undo, which brings the conversation back whole without
/// its folder ever being removed, and the row returns in its place with the keyboard on it.
#[test]
fn the_bin_asks_first_and_undo_on_the_toast_brings_the_conversation_back_whole() {
    for theme in [ThemeKind::Light, ThemeKind::Dark] {
        let (mut h, rig, chats) = chat_history(theme);
        let review = chats[2];
        let whole = rig.store.kept(review).unwrap();
        let undo_label = h.state().session.as_ref().and_then(|s| s.undo_label().map(str::to_string));
        assert!(!ids(&h).iter().any(|i| i == "workspace.chat.history.2.delete"), "no bin before the pointer comes");
        let row = rect_of(&h, "workspace.chat.history.2");
        point_at(&mut h, row.center());
        let bin = rect_of(&h, "workspace.chat.history.2.delete");
        assert!(row.contains(bin.center()) && bin.center().x > row.center().x, "{theme:?}: the bin at the row's right");
        click(&mut h, bin.center());
        for line in [
            "Delete this conversation?",
            "Review the checkout package · 12 messages with Codex, yesterday",
            "It is removed from this project's conversation list.",
            "Cancel",
            "Delete",
        ] {
            assert!(painted_has(&h, line), "{theme:?}: {line:?} in {:?}", painted(&h));
        }
        assert!(painted(&h).iter().any(|t| t.starts_with("It stays in the project's saved history: anyone with a copy")), "{theme:?}");
        assert!(!painted_has(&h, "Its reply in progress stops first."), "no reply runs");
        assert_eq!(focused(&h).as_deref(), Some("workspace.chat.delete.cancel"), "{theme:?}: the focus starts on Cancel");
        key(&mut h, egui::Key::Escape, egui::Modifiers::NONE);
        h.run();
        assert!(h.state().chat_panel.ask.is_none() && rig.store.kept(review).is_some(), "Escape cancels");
        assert_eq!(focused(&h).as_deref(), Some("workspace.chat.history.2"), "{theme:?}: the focus is back on the row");
        point_at(&mut h, row.center());
        let bin = rect_of(&h, "workspace.chat.history.2.delete");
        click(&mut h, bin.center());
        let at = rect_of(&h, "workspace.chat.delete.confirm").center();
        click(&mut h, at);
        h.run();
        assert!(rig.store.kept(review).is_none(), "{theme:?}: deleted");
        assert_eq!(rig.store.log.lock().unwrap().iter().filter(|k| **k == "delete").count(), 1);
        assert!(!painted(&h).iter().any(|t| t == "Review the checkout package"), "{theme:?}: gone from the list");
        assert!(painted_has(&h, "Review the checkout package deleted · still in the project's saved history"), "{theme:?}: {:?}", painted(&h));
        assert!(painted_has(&h, "Undo"));
        assert_eq!(focused(&h).as_deref(), Some("workspace.chat.history.2"), "{theme:?}: the next row takes the keyboard");
        assert_eq!(h.state().session.as_ref().and_then(|s| s.undo_label().map(str::to_string)), undo_label, "the model's undo is untouched");
        assert_eq!(h.state().chat_panel.chat.as_ref().map(|c| c.id), Some(chats[0]), "the open conversation stays open");
        assert!(forgotten(&rig).is_empty(), "the folder waits while Undo is offered");
        let at = rect_of(&h, "workspace.chat.toast.undo").center();
        click(&mut h, at);
        h.run();
        let back = rig.store.kept(review).unwrap();
        assert_eq!((back.row, back.turns, back.messages), (whole.row.clone(), whole.turns.clone(), whole.messages.clone()), "{theme:?}: whole");
        assert!(!ids(&h).iter().any(|i| i == "workspace.chat.toast"), "the toast is gone");
        h.run();
        assert!(painted(&h).iter().any(|t| t == "Review the checkout package"), "{theme:?}: back in the list");
        assert_eq!(focused(&h).as_deref(), Some("workspace.chat.history.2"), "{theme:?}: in its place, with the keyboard on it");
        later(&mut h, &rig, 60);
        assert!(forgotten(&rig).is_empty(), "{theme:?}: a conversation brought back keeps its folder");
        // The pointer was used last: no ring shows on the row the keyboard is on.
        assert!(!crate::settings::keyboard_last(&h.ctx));
    }
}

/// The row's menu (right-click, the menu key, ⇧F10) and ⌫ or Delete on the focused row open the
/// same confirmation; the toast stays while the pointer is on it and closes eight seconds after,
/// only then letting the folder go; ⌘Z meanwhile is the model's undo and never brings the
/// conversation back; and while the toast is up, a new conversation skips the deleted one's label.
#[test]
fn the_menu_and_the_keys_ask_the_same_and_the_folder_goes_only_when_the_toast_closes() {
    let (mut h, rig, chats) = chat_history(ThemeKind::Light);
    let row = rect_of(&h, "workspace.chat.history.0");
    // With the canvas holding the keys, the menu's keys never reach it.
    h.state_mut().canvas.focused = true;
    let selected = h.state().session.as_ref().unwrap().view().selection.clone();
    let revision = h.state().session.as_ref().unwrap().revision();
    right_click(&mut h, row.center());
    for k in [egui::Key::ArrowDown, egui::Key::ArrowUp, egui::Key::Backspace] {
        key(&mut h, k, egui::Modifiers::NONE);
    }
    let session = h.state().session.as_ref().unwrap();
    assert_eq!((session.revision(), &session.view().selection), (revision, &selected), "the canvas took none of the menu's keys");
    key(&mut h, egui::Key::Escape, egui::Modifiers::NONE);
    right_click(&mut h, row.center());
    assert!(ids(&h).iter().any(|i| i == "workspace.chat.history.menu.open") && painted_has(&h, "Delete conversation"), "{:?}", painted(&h));
    let at = rect_of(&h, "workspace.chat.history.menu.delete").center();
    click(&mut h, at);
    assert!(h.state().chat_panel.ask.as_ref().is_some_and(|a| a.chat == chats[0]), "the menu's item asks");
    key(&mut h, egui::Key::Escape, egui::Modifiers::NONE);
    // The keys on the focused row: ⌫, Delete, the menu key and ⇧F10.
    for (k, m, menu) in [
        (egui::Key::Backspace, egui::Modifiers::NONE, false),
        (egui::Key::Delete, egui::Modifiers::NONE, false),
        (egui::Key::Menu, egui::Modifiers::NONE, true),
        (egui::Key::F10, egui::Modifiers::SHIFT, true),
    ] {
        focus_on(&mut h, "workspace.chat.history.0");
        point_at(&mut h, egui::pos2(10.0, 600.0));
        key(&mut h, egui::Key::Tab, egui::Modifiers::SHIFT);
        key(&mut h, egui::Key::Tab, egui::Modifiers::NONE);
        assert_eq!(focused(&h).as_deref(), Some("workspace.chat.history.0"));
        assert!(ids(&h).iter().any(|i| i == "workspace.chat.history.0.delete"), "the bin shows on the row the keyboard is on");
        key(&mut h, k, m);
        h.run();
        if menu {
            assert!(
                h.state().chat_panel.row_menu.as_ref().is_some_and(|r| r.chat == chats[0] && r.reached == Some(0)),
                "{k:?} opens the menu, Open reached"
            );
            key(&mut h, egui::Key::ArrowDown, egui::Modifiers::NONE);
            key(&mut h, egui::Key::Enter, egui::Modifiers::NONE);
        }
        assert!(h.state().chat_panel.ask.as_ref().is_some_and(|a| a.chat == chats[0]), "{k:?} asks");
        assert!(crate::settings::keyboard_last(&h.ctx), "the keyboard was used last: focus rings show");
        key(&mut h, egui::Key::Escape, egui::Modifiers::NONE);
        assert!(h.state().chat_panel.ask.is_none());
    }
    // Deleted with Enter on the focused Delete button.
    focus_on(&mut h, "workspace.chat.history.0");
    key(&mut h, egui::Key::Delete, egui::Modifiers::NONE);
    key(&mut h, egui::Key::Tab, egui::Modifiers::NONE);
    assert_eq!(focused(&h).as_deref(), Some("workspace.chat.delete.confirm"), "Tab reaches Delete");
    key(&mut h, egui::Key::Enter, egui::Modifiers::NONE);
    h.run();
    let key_of = chats[0].to_string();
    assert!(rig.store.kept(chats[0]).is_none());
    // ⌘Z with nothing focused is the model's: the conversation stays deleted.
    h.ctx.memory_mut(|m| m.surrender_focus(crate::widgets::egui_id("workspace.chat.history.0")));
    key(&mut h, egui::Key::Z, egui::Modifiers::COMMAND);
    h.run();
    assert!(rig.store.kept(chats[0]).is_none() && !rig.store.log.lock().unwrap().contains(&"restore"), "⌘Z never restores");
    // A new conversation while Undo is offered: past Chat 5, the deleted one's label, the highest.
    let at = rect_of(&h, "workspace.chat.new").center();
    click(&mut h, at);
    ask_in_chat(&mut h, "A new question");
    assert_eq!(h.state().chat_panel.chat.as_ref().and_then(|c| c.origin.clone()).as_deref(), Some("Chat 6"));
    let at = rect_of(&h, "workspace.chat.history").center();
    click(&mut h, at);
    // The pointer on the toast holds it past its time.
    let toast = rect_of(&h, "workspace.chat.toast");
    point_at(&mut h, toast.center());
    for _ in 0..6 {
        later(&mut h, &rig, 5);
    }
    assert!(ids(&h).iter().any(|i| i == "workspace.chat.toast"), "held while the pointer is on it");
    point_at(&mut h, egui::pos2(10.0, 600.0));
    // So does the keyboard on Undo.
    focus_on(&mut h, "workspace.chat.toast.undo");
    for _ in 0..6 {
        later(&mut h, &rig, 5);
    }
    assert!(ids(&h).iter().any(|i| i == "workspace.chat.toast"), "held while the keyboard is on Undo");
    h.ctx.memory_mut(|m| m.surrender_focus(crate::widgets::egui_id("workspace.chat.toast.undo")));
    later(&mut h, &rig, 7);
    assert!(ids(&h).iter().any(|i| i == "workspace.chat.toast") && forgotten(&rig).is_empty(), "still within its eight seconds");
    later(&mut h, &rig, 2);
    h.run();
    assert!(!ids(&h).iter().any(|i| i == "workspace.chat.toast"), "closed");
    assert_eq!(forgotten(&rig), [key_of], "its folder goes once the toast closed, and only its");
}

/// Deleting the open conversation while its reply runs (AR-217): the confirmation says the reply
/// stops first; its reply so far is kept and its turn ends stopped, both written before the
/// deletion; the next row opens and takes the keyboard, then the one above; the last one deleted
/// leaves a new empty conversation (B2) and the keyboard on New conversation.
#[test]
fn the_open_conversation_stops_first_and_gives_way_to_the_next_one() {
    use crate::chat::ChatEvent;
    let (mut h, rig, chats) = chat_history(ThemeKind::Light);
    // The first conversation, open, asked again and answering. The panel itself keeps the history
    // shut while a reply runs; it is shown here as when one starts while it is open.
    let at = rect_of(&h, "workspace.chat.history").center();
    click(&mut h, at);
    ask_in_chat(&mut h, "And the rest?");
    chat_event(&mut h, &rig, ChatEvent::Text { delta: "So far".into() });
    h.state_mut().chat_panel.view = crate::chat_panel::View::History;
    h.run();
    let row = rect_of(&h, "workspace.chat.history.0");
    point_at(&mut h, row.center());
    let bin = rect_of(&h, "workspace.chat.history.0.delete");
    click(&mut h, bin.center());
    assert!(painted_has(&h, "Its reply in progress stops first."), "{:?}", painted(&h));
    let at = rect_of(&h, "workspace.chat.delete.confirm").center();
    click(&mut h, at);
    h.run();
    let log = rig.store.log.lock().unwrap().clone();
    let at = log.iter().position(|k| *k == "delete").unwrap();
    assert_eq!(&log[at - 2..=at], ["reply", "end", "delete"], "stopped and written first: {log:?}");
    let deleted = rig.store.deleted.lock().unwrap().last().unwrap().1.clone();
    assert_eq!(deleted.turns.last().unwrap().outcome, crate::chat_store::Outcome::Stopped);
    assert!(
        deleted.messages.iter().any(|m| matches!(&m.body, crate::chat_store::StoredBody::Reply { text, complete: false, .. } if text == "So far"))
    );
    assert!(rig.agents.running.lock().unwrap().is_empty(), "its program was let go of");
    h.run();
    assert_eq!(h.state().chat_panel.chat.as_ref().map(|c| c.id), Some(chats[1]), "the next one opens");
    assert_eq!(h.state().chat_panel.view, crate::chat_panel::View::History, "the history stays");
    assert_eq!(focused(&h).as_deref(), Some("workspace.chat.history.0"));
    // The last row of the list, open: the one above opens.
    let last = rect_of(&h, "workspace.chat.history.3").center();
    click(&mut h, last);
    let at = rect_of(&h, "workspace.chat.history").center();
    click(&mut h, at);
    focus_on(&mut h, "workspace.chat.history.3");
    key(&mut h, egui::Key::Delete, egui::Modifiers::NONE);
    key(&mut h, egui::Key::Tab, egui::Modifiers::NONE);
    key(&mut h, egui::Key::Enter, egui::Modifiers::NONE);
    h.run();
    assert_eq!(h.state().chat_panel.chat.as_ref().map(|c| c.id), Some(chats[3]), "the one above opens");
    assert_eq!(focused(&h).as_deref(), Some("workspace.chat.history.2"), "the row above takes the keyboard");
    // Then every other one: the last leaves a new, empty conversation and New conversation.
    for _ in 0..3 {
        focus_on(&mut h, "workspace.chat.history.0");
        key(&mut h, egui::Key::Delete, egui::Modifiers::NONE);
        key(&mut h, egui::Key::Tab, egui::Modifiers::NONE);
        key(&mut h, egui::Key::Enter, egui::Modifiers::NONE);
        h.run();
    }
    assert!(rig.store.chats.lock().unwrap().is_empty());
    let shown = h.state().chat_panel.chat.as_ref().unwrap();
    assert!(shown.turns.is_empty() && shown.origin.is_none(), "a new, empty conversation");
    assert_eq!(focused(&h).as_deref(), Some("workspace.chat.new"));
}

/// A deletion confirmed while its conversation's question is still on its way to the project waits
/// for it: the question lands first, its turn ends stopped, then the deletion; Undo then brings
/// back a conversation with no turn left running (AR-217).
#[test]
fn a_deletion_waits_for_a_question_on_its_way() {
    let (mut h, rig, chats) = chat_history(ThemeKind::Light);
    let at = rect_of(&h, "workspace.chat.history").center();
    click(&mut h, at);
    rig.store.hold.store(true, std::sync::atomic::Ordering::SeqCst);
    ask_in_chat(&mut h, "A question on its way");
    assert!(h.state().chat_panel.chat.as_ref().unwrap().step.busy(), "the question waits for the writer");
    h.state_mut().chat_panel.view = crate::chat_panel::View::History;
    h.run();
    let row = rect_of(&h, "workspace.chat.history.0");
    point_at(&mut h, row.center());
    let bin = rect_of(&h, "workspace.chat.history.0.delete");
    click(&mut h, bin.center());
    let at = rect_of(&h, "workspace.chat.delete.confirm").center();
    click(&mut h, at);
    assert!(!rig.store.log.lock().unwrap().contains(&"delete"), "the deletion waits for the question");
    rig.store.release();
    h.run();
    h.run();
    let log = rig.store.log.lock().unwrap().clone();
    let at = log.iter().position(|k| *k == "delete").expect("deleted once the question landed");
    assert_eq!(&log[at - 2..=at], ["ask", "end", "delete"], "{log:?}");
    let at = rect_of(&h, "workspace.chat.toast.undo").center();
    click(&mut h, at);
    h.run();
    let back = rig.store.kept(chats[0]).unwrap();
    assert!(back.turns.iter().all(|t| t.outcome != crate::chat_store::Outcome::Running), "no turn left running");
}

/// Undo pressed before the deletion finished runs once it has, and keeps the folder; a deletion
/// whose toast is still up when its project closes, or when Archforge quits, lets its folder go
/// then; one still waiting for the project then hands its answer to the host, which lets the
/// folder go only once deleted, and an Undo still waiting keeps it once the conversation is back
/// (AR-217).
#[test]
fn undo_before_the_deletion_finished_runs_after_it_and_closing_or_quitting_settles_the_folders() {
    let (mut h, rig, chats) = chat_history(ThemeKind::Light);
    rig.store.hold.store(true, std::sync::atomic::Ordering::SeqCst);
    let row = rect_of(&h, "workspace.chat.history.2");
    point_at(&mut h, row.center());
    let bin = rect_of(&h, "workspace.chat.history.2.delete");
    click(&mut h, bin.center());
    let at = rect_of(&h, "workspace.chat.delete.confirm").center();
    click(&mut h, at);
    assert!(rig.store.kept(chats[2]).is_some(), "the writer has not taken the deletion yet");
    let at = rect_of(&h, "workspace.chat.toast.undo").center();
    click(&mut h, at);
    assert!(rig.store.kept(chats[2]).is_some(), "the writer has taken neither yet");
    rig.store.release();
    h.run();
    h.run();
    let log = rig.store.log.lock().unwrap().clone();
    assert_eq!(log.iter().rev().take(2).rev().copied().collect::<Vec<_>>(), ["delete", "restore"], "{log:?}");
    assert!(rig.store.kept(chats[2]).is_some(), "brought back");
    assert!(forgotten(&rig).is_empty());
    // A toast still up when the project closes: its folder goes.
    let row = rect_of(&h, "workspace.chat.history.3");
    point_at(&mut h, row.center());
    let bin = rect_of(&h, "workspace.chat.history.3.delete");
    click(&mut h, bin.center());
    let at = rect_of(&h, "workspace.chat.delete.confirm").center();
    click(&mut h, at);
    assert!(forgotten(&rig).is_empty());
    h.state_mut().close_project();
    h.run();
    assert_eq!(forgotten(&rig), [chats[3].to_string()], "closing the project settles it");
    // And at quit: a toast still up in the project shown lets its folder go.
    let (mut h, rig, chats) = chat_history(ThemeKind::Light);
    let row = rect_of(&h, "workspace.chat.history.4");
    point_at(&mut h, row.center());
    let bin = rect_of(&h, "workspace.chat.history.4.delete");
    click(&mut h, bin.center());
    let at = rect_of(&h, "workspace.chat.delete.confirm").center();
    click(&mut h, at);
    h.state_mut().before_exit();
    assert_eq!(forgotten(&rig), [chats[4].to_string()], "quitting settles it");
    // Quitting while a deletion, and another one's Undo, wait for the writer: the host takes
    // their answers; the deleted one's folder goes, the one brought back keeps its own.
    let (mut h, rig, chats) = chat_history(ThemeKind::Light);
    rig.store.hold.store(true, std::sync::atomic::Ordering::SeqCst);
    for (row, undo) in [(4, false), (3, true)] {
        let r = rect_of(&h, &format!("workspace.chat.history.{row}"));
        point_at(&mut h, r.center());
        let bin = rect_of(&h, &format!("workspace.chat.history.{row}.delete"));
        click(&mut h, bin.center());
        let at = rect_of(&h, "workspace.chat.delete.confirm").center();
        click(&mut h, at);
        if undo {
            let at = rect_of(&h, "workspace.chat.toast.undo").center();
            click(&mut h, at);
        }
    }
    h.state_mut().before_exit();
    assert!(forgotten(&rig).is_empty(), "nothing is removed before the project answers");
    rig.store.release();
    rig.agents.settle_after();
    assert_eq!(forgotten(&rig), [chats[4].to_string()], "the deleted one's folder alone");
    assert!(rig.store.kept(chats[3]).is_some() && rig.store.kept(chats[4]).is_none());
}

/// Undo pressed before the deletion answered, then the project closed (AR-218): the host is handed
/// both answers. When the deletion fails and the restoration after it fails too (the project could
/// not read its list), the conversation is still listed and its folder stays; only a deletion that
/// was made and a restoration that did not bring it back let the folder go.
#[test]
fn an_undo_before_a_failed_deletion_keeps_the_folder_of_a_conversation_still_listed_at_close() {
    use crate::chat_store::{Answer, Refusal};
    for (deletion, goes) in [(Err(Refusal::Failed("the project is busy".into())), false), (Ok(Answer::Deleted { before: "0".repeat(32) }), true)] {
        let (mut h, rig, chats) = chat_history(ThemeKind::Light);
        rig.store.hold.store(true, std::sync::atomic::Ordering::SeqCst);
        let row = rect_of(&h, "workspace.chat.history.2");
        point_at(&mut h, row.center());
        let bin = rect_of(&h, "workspace.chat.history.2.delete");
        click(&mut h, bin.center());
        let at = rect_of(&h, "workspace.chat.delete.confirm").center();
        click(&mut h, at);
        let at = rect_of(&h, "workspace.chat.toast.undo").center();
        click(&mut h, at);
        h.state_mut().close_project();
        h.run();
        // The writer answers the deletion as the case says, then refuses the restoration.
        let held: Vec<_> = std::mem::take(&mut *rig.store.held.lock().unwrap());
        let kinds: Vec<&str> = held.iter().map(|(w, _)| w.kind()).collect();
        assert_eq!(kinds, ["delete", "restore"], "both wait for the writer");
        let mut answers = [deletion.clone(), Err(Refusal::Failed("no deletion of it was asked in this project".into()))].into_iter();
        for (_, tx) in held {
            let _ = tx.send(answers.next().unwrap());
        }
        rig.agents.settle_after();
        let key = chats[2].to_string();
        if goes {
            assert_eq!(forgotten(&rig), [key], "deleted and not brought back: its folder goes");
        } else {
            assert!(forgotten(&rig).is_empty(), "not deleted: the folder of a conversation still listed stays");
            assert!(rig.store.kept(chats[2]).is_some(), "still listed");
        }
    }
}

/// A conversation started while the host removes its private folder (AR-218), as a copy of the
/// project can: the host refuses the start, the turn says "No answer" with Send again and nothing
/// hangs; the refused start keeps the folder although the deletion went through, and once the
/// removal is done, Send again starts it.
#[test]
fn a_conversation_started_while_its_folder_is_being_removed_says_no_answer_and_sends_again_once_done() {
    use crate::ai_agents::FolderGoes;
    use crate::chat_store::Answer;
    let (mut h, rig) = chat_harness(ThemeKind::Light, true);
    ask_in_chat(&mut h, "First question");
    chat_event(&mut h, &rig, crate::chat::ChatEvent::TurnEnded(crate::chat::TurnEnd::Completed));
    let key = crate::chat_fixture::key(h.state());
    let _ = crate::chat::end(h.state(), &key);
    h.run();
    assert!(rig.agents.running.lock().unwrap().is_empty(), "its program ended");
    // A copy of the project deleted it, and its folder's removal waits for that project's answer.
    let (tx, rx) = std::sync::mpsc::channel();
    let removal = crate::ai_agents::AgentHost::forget_after(&*rig.agents, &key, vec![(rx, FolderGoes::IfDeleted)]);
    let starts = chat_calls(&rig).0;
    ask_in_chat(&mut h, "Second question");
    assert_eq!(chat_calls(&rig).0, starts + 1, "a start was asked");
    assert!(rig.agents.running.lock().unwrap().is_empty(), "and refused");
    assert!(painted_has(&h, "No answer") && painted_has(&h, "Claude stopped before answering. Nothing was changed."), "{:?}", painted(&h));
    assert!(ids(&h).iter().any(|i| i == "workspace.chat.turn.2.retry"), "Send again is offered");
    assert!(ids(&h).iter().any(|i| i == "workspace.chat.send"), "the composer is free: nothing hangs");
    // The copy's deletion went through, but a panel here asked for the conversation: its folder stays.
    tx.send(Ok(Answer::Deleted { before: "0".repeat(32) })).unwrap();
    rig.agents.settle_after();
    assert_eq!(removal.recv_timeout(std::time::Duration::from_secs(5)).unwrap(), Ok(false));
    let at = rect_of(&h, "workspace.chat.turn.2.retry").center();
    click(&mut h, at);
    assert_eq!(*rig.agents.running.lock().unwrap(), std::slice::from_ref(&key), "it starts now");
    assert!(rig.agents.sent.lock().unwrap().iter().any(|(c, t)| *c == key && t.starts_with("Second question")), "and gets the question");
    assert!(forgotten(&rig).is_empty());
}

/// When a re-read of the list fails, the rows read before stay and their changes are off, saying
/// why: the bin and the menu's item are disabled and ⌫ asks nothing (AR-217).
#[test]
fn with_chat_writing_off_the_bin_and_the_item_are_disabled_and_say_why() {
    let (mut h, rig, chats) = chat_history(ThemeKind::Dark);
    let at = rect_of(&h, "workspace.chat.history").center();
    click(&mut h, at);
    *rig.store.unreadable.lock().unwrap() = Some("the table chat_turn does not have the shape Archforge writes".into());
    click(&mut h, at);
    h.run();
    assert!(painted_has(&h, "Review the checkout package"), "the rows read before stay");
    let why = "The conversations in this project cannot be changed: the table chat_turn does not have the shape Archforge writes";
    let refused = crate::chat_delete::refusal(&h.state().chat_panel, &Ok(rig.store.kept(chats[2]).unwrap().row));
    assert_eq!(refused.as_deref(), Some(why));
    let row = rect_of(&h, "workspace.chat.history.2");
    point_at(&mut h, row.center());
    let bin = rect_of(&h, "workspace.chat.history.2.delete");
    click(&mut h, bin.center());
    assert!(h.state().chat_panel.ask.is_none(), "the disabled bin asks nothing");
    right_click(&mut h, row.center());
    let item = rect_of(&h, "workspace.chat.history.menu.delete").center();
    click(&mut h, item);
    assert!(h.state().chat_panel.ask.is_none(), "nor the item");
    focus_on(&mut h, "workspace.chat.history.2");
    key(&mut h, egui::Key::Delete, egui::Modifiers::NONE);
    assert!(h.state().chat_panel.ask.is_none() && rig.store.kept(chats[2]).is_some(), "nor ⌫");
    // A row that cannot be read gets a disabled bin of its own.
    let unreadable = crate::chat_store::Listed { id: chats[0], entry: Err("its provider is not one Archforge knows".into()) };
    let panel = crate::chat_panel::Panel::default();
    assert_eq!(crate::chat_delete::refusal(&panel, &unreadable.entry).as_deref(), Some("This conversation cannot be read"));
}

